/* 
// ---------------------------------------------------------------------------
// Road streaming (docs/roads.md "Road streaming"). This project streams its
// roads, so buildRoads is never called: roadStreamSetup PLANS the scene into
// items - every strip chunk buildRoads would cut, every baked row - and
// roadStreamUpdate keeps the items within ROAD_STREAM_RADIUS of the view
// focus built, nearest first, at most ROAD_STREAM_BUDGET vertex units a
// frame, dropping what has moved beyond ROAD_STREAM_KEEP. Every piece below
// that BUILDS geometry is cut from the non-streaming build's own source by
// the codegen (src/roadstream.cpp), so a streamed chunk is the chunk
// buildRoads makes.
// ---------------------------------------------------------------------------
constexpr float ROAD_STREAM_RADIUS = 260.0F;
constexpr float ROAD_STREAM_KEEP = 300.0F;
constexpr float ROAD_STREAM_CELL = 64.0F;
constexpr int ROAD_STREAM_BUDGET = 600;
enum : unsigned char {
  RS_STRIP = 0, RS_JUNCTION = 1, RS_SPILL = 2, RS_EDGE = 3, RS_KERB = 4,  // the surface
  RS_BRIDGE = 5, RS_DETAIL = 6, RS_FURN = 7,                             // drawn only
  RS_BRIDGE_BOX = 8, RS_FURN_BOX = 9                                     // collision only
};
// Tables on disk: read this much further out than the build radius (less
// than the keep band, so an item dropped behind is not read again), keep at
// most ROAD_STREAM_CACHE bytes read ahead, and read with ROAD_IO_SLOTS items
// in flight.
constexpr float ROAD_STREAM_PREFETCH = 30.0F;
constexpr size_t ROAD_STREAM_CACHE = 1048576;
constexpr int ROAD_IO_SLOTS = 8;
alignas(16) static unsigned char rsIoStack[16 * 1024];

// One absolute seek, then reads of at most 16 KB - the engine's proven
// pattern on the PS2 host filesystem (audio_song.cpp), and a short chunk
// keeps a main-thread file call (a log line, a texture) from waiting behind a
// whole item. A short read is a failure, never a partial item.
static bool rsReadRange(int fd, unsigned int at, unsigned int bytes, unsigned char* buf) {
  if (fd < 0) return false;
  if (lseek(fd, (off_t)at, SEEK_SET) != (off_t)at) return false;
  unsigned int done = 0;
  while (done < bytes) {
    unsigned int n = bytes - done;
    if (n > 16384U) n = 16384U;
    const int got = (int)read(fd, buf + done, n);
    if (got <= 0) return false;
    done += (unsigned int)got;
  }
  return true;
}

Tyra::Texture* TerrainGame::roadStreamTexture(int tex) {
  if (tex < 0 || tex >= ROAD_TEXTURE_COUNT) return nullptr;
  if (!roadTextures_[tex]) roadTextures_[tex] = acquireTexture(ROAD_TEXTURE_PATHS[tex]);
  return roadTextures_[tex];
}

// One road's strip chunks: buildRoads' own tessellator. item < 0 PLANS the
// whole road (every chunk into rsScratch_, recorded as an item with its
// resume state); item >= 0 REPLAYS that one chunk into procChunks[rsTarget_]
// and stops where buildRoads would have started the next one.
void TerrainGame::roadStreamTessellate(int ri, int item) {
  const int scene = ROAD_DEFS[ri].scene;
  (void)scene;
  const unsigned int stripRun = 75u;
  // The physical-GS smear that originally parked this at 0 came from unbounded
  // road V coordinates, not from strip topology. Each chunk now rebases V by a
  // whole repeat before either emitter sees it; hardware A/B keeps lane marks
  // intact while the strip removes hundreds of packages from a district.
  // Keep 0 as the triangle-list control arm for future renderer work.
#ifndef TYRA_STRIP_ROADS
#define TYRA_STRIP_ROADS 1
#endif
  const bool useStrips = TYRA_STRIP_ROADS && minPackageSize() >= stripRun;
  const Tyra::Color grey(128.0F, 128.0F, 128.0F, 128.0F);
  bool any = false;
    const RoadDefRt& rd = ROAD_DEFS[ri];
    if (rd.pointCount < 2) return;
    any = true;
    Tyra::Texture* tex = nullptr;
    if (rd.tex >= 0 && rd.tex < ROAD_TEXTURE_COUNT) {
      if (!roadTextures_[rd.tex])
        roadTextures_[rd.tex] = acquireTexture(ROAD_TEXTURE_PATHS[rd.tex]);
      tex = roadTextures_[rd.tex];
    }
    const float* pts = &ROAD_POINTS[rd.first];
    const int n = rd.pointCount;
    const float hw = 0.5F * (rd.width > 0.1F ? rd.width : 0.1F);
    const float sampleStep = rd.sampleStep >= 1.0F
                                 ? (rd.sampleStep <= 2.0F ? rd.sampleStep : 2.0F)
                                 : 1.0F;
    int crossSteps = (int)ceilf((hw * 2.0F) / 0.5F);
    if (crossSteps < 1) crossSteps = 1;
    // Catmull-Rom; repeated endpoint means periodic controls, as in roadgen.
    const bool closed = n >= 4 && pts[0] == pts[(n - 1) * 2] &&
                        pts[1] == pts[(n - 1) * 2 + 1];
    auto ptAt = [&](int i, float* x, float* z) {
      if (closed) {
        i = (i % (n - 1) + n - 1) % (n - 1);
      } else {
        if (i < 0) i = 0;
        if (i > n - 1) i = n - 1;
      }
      *x = pts[i * 2];
      *z = pts[i * 2 + 1];
    };
    auto cr = [](float p0, float p1, float p2, float p3, float t) {
      const float t2 = t * t, t3 = t2 * t;
      return 0.5F * ((2.0F * p1) + (-p0 + p2) * t +
                     (2.0F * p0 - 5.0F * p1 + 4.0F * p2 - p3) * t2 +
                     (-p0 + 3.0F * p1 - 3.0F * p2 + p3) * t3);
    };
    auto sampleAt = [&](int seg, float t, float* x, float* z) {
      float x0, z0, x1, z1, x2, z2, x3, z3;
      ptAt(seg - 1, &x0, &z0);
      ptAt(seg, &x1, &z1);
      ptAt(seg + 1, &x2, &z2);
      ptAt(seg + 2, &x3, &z3);
      *x = cr(x0, x1, x2, x3, t);
      *z = cr(z0, z1, z2, z3, t);
    };
    ProcChunk* c = nullptr;
    int stationsInChunk = 0;
    float chunkVBase = 0.0F;
    // Strip run state, per chunk. TWIN NOTICE: roadgen.cpp's
    // tessellateStrips - the same packer, vertex for vertex.
    size_t runStart = 0;
    bool alongOpen = false;
    auto runLen = [&]() { return c->vertices.size() - runStart; };
    // One vertex into the open run. A run that fills MID-STRIP carries the
    // two-vertex overlap into the next one, or the triangle across the cut is
    // lost. That is the only place a run ever ends anywhere but at its full
    // length, which is what lets the packages BE the runs.
    auto pushRaw = [&](const Tyra::Vec4& p, const Tyra::Vec4& s) {
      if (runLen() == (size_t)stripRun) {
        const size_t m = c->vertices.size();
        const Tyra::Vec4 pa = c->vertices[m - 2], pb = c->vertices[m - 1];
        const Tyra::Vec4 sa = c->sts[m - 2], sb = c->sts[m - 1];
        runStart = m;
        c->vertices.push_back(pa); c->sts.push_back(sa); c->colors.push_back(grey);
        c->vertices.push_back(pb); c->sts.push_back(sb); c->colors.push_back(grey);
      }
      c->vertices.push_back(p); c->sts.push_back(s); c->colors.push_back(grey);
    };
    // Begin an unrelated strip inside the open run: repeat the run's last
    // vertex and the incoming strip's first. Four zero-area triangles, and
    // the fifth is the incoming strip's own first real one.
    auto startStrip = [&](const Tyra::Vec4& p, const Tyra::Vec4& s) {
      if (runLen() > 0) {
        const Tyra::Vec4 lp = c->vertices.back();
        const Tyra::Vec4 ls = c->sts.back();
        pushRaw(lp, ls);
        pushRaw(p, s);
      }
      pushRaw(p, s);
    };
    // A chunk's LAST run owes only the multiple of 3 the VU1 vertex loops
    // need; a count that is not runs off into VU1 memory. The padding repeats
    // the last vertex, which makes a degenerate triangle the GS rasterises to
    // nothing.
    auto closeChunk = [&]() {
      if (!useStrips || c == nullptr) return;
      const size_t target = ((runLen() + 2) / 3) * 3;
      while (runLen() < target) {
        c->vertices.push_back(c->vertices.back());
        c->sts.push_back(c->sts.back());
        c->colors.push_back(grey);
      }
      runStart = c->vertices.size();
    };
    std::vector<float> px0((size_t)crossSteps + 1);
    std::vector<float> py0((size_t)crossSteps + 1);
    std::vector<float> pz0((size_t)crossSteps + 1);
    // Where this station pair is cut laterally. Hoisted out of the station
    // loop: this runs on the EE at scene load, once per station of every road
    // in the district, and a per-station heap allocation there is not free.
    std::vector<int> cuts;
    cuts.reserve((size_t)crossSteps + 1);
    float lv0 = 0.0F;
    bool havePrev = false;
    float arc = 0.0F, prevX = 0.0F, prevZ = 0.0F;
    sampleAt(0, 0.0F, &prevX, &prevZ);
    // ROAD STREAMING: a replay resumes at the station BEFORE its chunk's
    // first span, with the arc state that station started from - the
    // state the plan pass recorded there. That station emits no span
    // (havePrev is still false), it only rebuilds the row the span needs.
    int rsSeg0 = 0, rsK0 = 0;
    if (item >= 0) {
      const RsItem& rsIt = rsItems_[(size_t)item];
      rsSeg0 = rsIt.b >> 16;
      rsK0 = rsIt.b & 0xFFFF;
      arc = rsIt.arc;
      prevX = rsIt.px;
      prevZ = rsIt.pz;
    }
    int rsLastSeg = 0, rsLastK = 0;
    float rsLastArc = 0.0F, rsLastX = prevX, rsLastZ = prevZ;
    for (int seg = rsSeg0; seg < n - 1; ++seg) {
      float ax, az, bx, bz;
      ptAt(seg, &ax, &az);
      ptAt(seg + 1, &bx, &bz);
      const float segLen =
          sqrtf((bx - ax) * (bx - ax) + (bz - az) * (bz - az));
      const int steps = segLen > sampleStep
                            ? (int)(segLen / sampleStep) + 1
                            : 1;
      for (int k = (seg == rsSeg0 ? rsK0 : (seg == 0 ? 0 : 1)); k <= steps; ++k) {
        const int rsSeg = seg, rsK = k;
        const float rsArc = arc, rsX = prevX, rsZ = prevZ;
        const float t = (float)k / (float)steps;
        float cx2, cz2, dx2, dz2;
        sampleAt(seg, t, &cx2, &cz2);
        float fromX = cx2, fromZ = cz2;
        if (closed && seg == n - 2 && t == 1.0F) {
          sampleAt(0, 0.05F, &dx2, &dz2);
        } else if (t + 0.05F <= 1.0F || seg + 1 < n - 1) {
          if (t + 0.05F <= 1.0F)
            sampleAt(seg, t + 0.05F, &dx2, &dz2);
          else
            sampleAt(seg + 1, 0.05F, &dx2, &dz2);
        } else {
          sampleAt(seg, fmaxf(0.0F, t - 0.05F), &fromX, &fromZ);
          dx2 = cx2;
          dz2 = cz2;
        }
        float tx = dx2 - fromX, tz = dz2 - fromZ;
        const float tl = sqrtf(tx * tx + tz * tz);
        if (tl > 1e-6F) {
          tx /= tl;
          tz /= tl;
        } else {
          tx = 0.0F;
          tz = 1.0F;
        }
        const float rxu = tz * hw, rzu = -tx * hw;
        // Geometry spacing is authored, but texture arc length always keeps
        // the original one-unit integration cadence. A cheaper road must not
        // make its lane markings slide or accumulate a different repeat.
        const float prevT = k > 0 ? (float)(k - 1) / (float)steps : 0.0F;
        int arcSteps = k > 0 ? (int)ceilf((t - prevT) * segLen / 1.0F) : 0;
        if (k > 0 && arcSteps < 1) arcSteps = 1;
        for (int ak = 1; ak <= arcSteps; ++ak) {
          const float at = prevT + (t - prevT) *
                                       ((float)ak / (float)arcSteps);
          float apx, apz;
          sampleAt(seg, at, &apx, &apz);
          arc += sqrtf((apx - prevX) * (apx - prevX) +
                       (apz - prevZ) * (apz - prevZ));
          prevX = apx;
          prevZ = apz;
        }
        prevX = cx2;
        prevZ = cz2;
        const float v = arc / 4.0F;
        std::vector<float> nx((size_t)crossSteps + 1);
        std::vector<float> ny((size_t)crossSteps + 1);
        std::vector<float> nz((size_t)crossSteps + 1);
        for (int j = 0; j <= crossSteps; ++j) {
          const float u = (float)j / (float)crossSteps;
          const float side = u * 2.0F - 1.0F;
          nx[(size_t)j] = cx2 + rxu * side;
          nz[(size_t)j] = cz2 + rzu * side;
          ny[(size_t)j] =
              terrainHeightAt(nx[(size_t)j], nz[(size_t)j]) + 0.12F + rd.lift;
        }
        if (havePrev) {
          // Two triangles per lateral cell, CCW seen from above - the twin's
          // stitch, emitted station by station so a chunk boundary never
          // leaves a gap (the previous row is re-used as the base).
          // Exact lateral reduction: every dense sample must lie on the
          // proposed quad plane, and the quad must be an affine parallelogram
          // so its two triangles interpolate ST as the cells they replace do.
          // The reduction is per SUB-SPAN rather than all-or-nothing, because
          // a road is a decal on a heightfield sampled far more finely than
          // the heightfield itself - runs of lateral cells inside one terrain
          // triangle are exactly coplanar even when the full width is not.
          // The two budgets are the roadgen.hpp twin's kSpanFlatness (surface,
          // and with it the T-junction) and kSpanShear (UV, tripped by bends).
          auto spanIsExact = [&](int j0, int j1) {
            const float ax = px0[(size_t)j0], ay = py0[(size_t)j0];
            const float az = pz0[(size_t)j0];
            const float bx = px0[(size_t)j1], by = py0[(size_t)j1];
            const float bz = pz0[(size_t)j1];
            const float dx = nx[(size_t)j0], dy = ny[(size_t)j0];
            const float dz = nz[(size_t)j0];
            const float cx = nx[(size_t)j1], cy = ny[(size_t)j1];
            const float cz = nz[(size_t)j1];
            const float ux = bx - ax, uy = by - ay, uz = bz - az;
            const float vx = dx - ax, vy = dy - ay, vz = dz - az;
            const float pnx = uy * vz - uz * vy;
            const float pny = uz * vx - ux * vz;
            const float pnz = ux * vy - uy * vx;
            const float pnl = sqrtf(pnx * pnx + pny * pny + pnz * pnz);
            if (!(pnl > 1e-6F)) return false;
            const float qax = (bx - ax) - (cx - dx);
            const float qay = (by - ay) - (cy - dy);
            const float qaz = (bz - az) - (cz - dz);
            if (sqrtf(qax * qax + qay * qay + qaz * qaz) > 0.05F)
              return false;
            for (int r = 0; r < 2; ++r)
              for (int j = j0; j <= j1; ++j) {
                const float qx = r ? nx[(size_t)j] : px0[(size_t)j];
                const float qy = r ? ny[(size_t)j] : py0[(size_t)j];
                const float qz = r ? nz[(size_t)j] : pz0[(size_t)j];
                const float dist = fabsf(pnx * (qx - ax) + pny * (qy - ay) +
                                         pnz * (qz - az)) / pnl;
                if (dist > 0.00001F) return false;
              }
            return true;
          };
          // Keep the long-standing horizontal reduction, including curved
          // spans, as the roadgen.cpp twin does. It is the one case that does
          // NOT owe the affine check.
          bool flat = true;
          const float flatY = py0[0];
          for (int r = 0; r < 2 && flat; ++r)
            for (int j = 0; j <= crossSteps; ++j) {
              const float qy = r ? ny[(size_t)j] : py0[(size_t)j];
              if (fabsf(qy - flatY) > 0.00001F) { flat = false; break; }
            }
          cuts.clear();
          cuts.push_back(0);
          if (flat) {
            cuts.push_back(crossSteps);
          } else {
            // Greedy maximal runs. A single cell is the fallback and is never
            // tested, so this can only remove vertices from the dense mesh.
            int j0 = 0;
            while (j0 < crossSteps) {
              int j1 = j0 + 1;
              while (j1 < crossSteps && spanIsExact(j0, j1 + 1)) ++j1;
              cuts.push_back(j1);
              j0 = j1;
            }
          }
          const bool collapsed = cuts.size() == 2;
          // Amortize EE bag/bounds work on flat streets, without making dense
          // slopes unbounded or joining a whole road into one culling box.
          // The budget is in the currency the chunk actually holds, so the
          // two emitters cut a road into the SAME number of chunks only by
          // accident - what matters is that a run never straddles one.
          const size_t spanVertices =
              useStrips
                  ? (collapsed
                         ? (alongOpen ? (size_t)2 : (size_t)4)
                         : (2 * cuts.size() + 2))
                  : (cuts.size() - 1) * 6;
          if (!c || stationsInChunk >= 36 ||
              v - chunkVBase >= 16.0F ||
              c->vertices.size() + spanVertices > 1800) {
            closeChunk();
            if (!roadStreamOpen(c, item, ri, rsLastSeg, rsLastK, rsLastArc,
                                rsLastX, rsLastZ))
              return;
            c->owner = -3;
            c->roadTex = tex;
            c->roadGrip = rd.grip;
            c->stripRun = useStrips ? (int)stripRun : 0;
            // Texture repeat is invariant under an integer V offset. Keep the
            // value local to this bag: long roads otherwise feed ever-growing
            // ST coordinates into the physical GS/VU path, where the lost
            // fractional precision can smear one texel over the whole road.
            chunkVBase = floorf(lv0);
            stationsInChunk = 0;
            runStart = 0;
            alongOpen = false;
          }
          // P is the previous station's row, N this one's.
          auto vAt = [&](int j, bool newRow) {
            return newRow ? Tyra::Vec4(nx[(size_t)j], ny[(size_t)j],
                                       nz[(size_t)j], 1.0F)
                          : Tyra::Vec4(px0[(size_t)j], py0[(size_t)j],
                                       pz0[(size_t)j], 1.0F);
          };
          auto sAt = [&](int j, bool newRow) {
            return Tyra::Vec4(rd.uInset + (1.0F - 2.0F * rd.uInset) *
                                              (float)j / (float)crossSteps,
                              (newRow ? v : lv0) - chunkVBase, 1.0F, 0.0F);
          };
          if (!useStrips) {
            for (size_t ci = 0; ci + 1 < cuts.size(); ++ci) {
              const int j = cuts[ci], j2 = cuts[ci + 1];
              const float u0 = rd.uInset + (1.0F - 2.0F * rd.uInset) *
                                               (float)j / (float)crossSteps;
              const float u1 = rd.uInset + (1.0F - 2.0F * rd.uInset) *
                                               (float)j2 / (float)crossSteps;
              const Tyra::Vec4 A(px0[(size_t)j], py0[(size_t)j],
                                 pz0[(size_t)j], 1.0F);
              const Tyra::Vec4 B(px0[(size_t)j2], py0[(size_t)j2],
                                 pz0[(size_t)j2], 1.0F);
              const Tyra::Vec4 C(nx[(size_t)j2], ny[(size_t)j2],
                                 nz[(size_t)j2], 1.0F);
              const Tyra::Vec4 D(nx[(size_t)j], ny[(size_t)j],
                                 nz[(size_t)j], 1.0F);
              const Tyra::Vec4 sA(u0, lv0 - chunkVBase, 1.0F, 0.0F);
              const Tyra::Vec4 sB(u1, lv0 - chunkVBase, 1.0F, 0.0F);
              const Tyra::Vec4 sC(u1, v - chunkVBase, 1.0F, 0.0F);
              const Tyra::Vec4 sD(u0, v - chunkVBase, 1.0F, 0.0F);
              c->vertices.push_back(A); c->sts.push_back(sA); c->colors.push_back(grey);
              c->vertices.push_back(B); c->sts.push_back(sB); c->colors.push_back(grey);
              c->vertices.push_back(C); c->sts.push_back(sC); c->colors.push_back(grey);
              c->vertices.push_back(A); c->sts.push_back(sA); c->colors.push_back(grey);
              c->vertices.push_back(C); c->sts.push_back(sC); c->colors.push_back(grey);
              c->vertices.push_back(D); c->sts.push_back(sD); c->colors.push_back(grey);
            }
          } else if (collapsed) {
            // A collapsed span is ONE full-width quad, so a street of them is
            // a grid one cell WIDE and many stations LONG - and a strip has
            // to run along the long axis or it buys nothing. Taken laterally
            // a collapsed span is 4 vertices plus a 2-vertex join against the
            // list's 6: break-even on the EE and 3x the GS primitives, two
            // thirds of them degenerate. Taken longitudinally it is 2
            // vertices per STATION, the same 0.35x the dense spans reach.
            // ... P[w], P[0], N[w], N[0] ... - successive triples are this
            // span's two triangles, cut along P[0]-N[w], which is the cut the
            // list stitch above makes. The other interleaving takes the other
            // diagonal and silently reshapes every non-planar quad.
            if (!alongOpen) {
              startStrip(vAt(crossSteps, false), sAt(crossSteps, false));
              pushRaw(vAt(0, false), sAt(0, false));
              alongOpen = true;
            }
            pushRaw(vAt(crossSteps, true), sAt(crossSteps, true));
            pushRaw(vAt(0, true), sAt(0, true));
          } else {
            // N[0], P[0], N[s], P[s], ... - same argument, same diagonal
            // P[j]-N[j+s], walked ACROSS the road instead. The cuts are no
            // longer uniformly spaced, which changes nothing here: the walk
            // visits them in order and the diagonal is the same one.
            alongOpen = false;
            startStrip(vAt(0, true), sAt(0, true));
            pushRaw(vAt(0, false), sAt(0, false));
            for (size_t ci = 1; ci < cuts.size(); ++ci) {
              pushRaw(vAt(cuts[ci], true), sAt(cuts[ci], true));
              pushRaw(vAt(cuts[ci], false), sAt(cuts[ci], false));
            }
          }
          ++stationsInChunk;
        }
        rsLastSeg = rsSeg;
        rsLastK = rsK;
        rsLastArc = rsArc;
        rsLastX = rsX;
        rsLastZ = rsZ;
        px0.swap(nx);
        py0.swap(ny);
        pz0.swap(nz);
        lv0 = v;
        havePrev = true;
      }
    }
    // This road's last chunk still has an open run.
    closeChunk();
    if (item < 0 && c) roadStreamPlanClose();
  (void)any;
}

bool TerrainGame::roadStreamOpen(ProcChunk*& c, int item, int ri, int seg, int k, float arc,
                                 float x, float z) {
  if (item >= 0) {
    if (c) return false;  // the replayed chunk is complete
    c = &procChunks[(size_t)rsTarget_];
    return true;
  }
  if (c) roadStreamPlanClose();
  RsItem it;
  it.kind = RS_STRIP;
  it.a = ri;
  it.b = (seg << 16) | (k & 0xFFFF);
  it.arc = arc;
  it.px = x;
  it.pz = z;
  rsItems_.push_back(it);
  rsBoxes_.push_back(RsBox{0.0F, 0.0F, 0.0F, 0.0F});
  rsScratch_.vertices.clear();
  rsScratch_.colors.clear();
  rsScratch_.sts.clear();
  c = &rsScratch_;
  return true;
}

// A planned strip chunk is complete in rsScratch_: its box, its size, the
// statistics buildRoads logs, and the spill heights it lifts.
void TerrainGame::roadStreamPlanClose() {
  RsItem& it = rsItems_.back();
  const ProcChunk& c = rsScratch_;
  it.verts = (int)c.vertices.size();
  RsBox b = {0.0F, 0.0F, 0.0F, 0.0F};
  if (!c.vertices.empty()) {
    b = RsBox{c.vertices[0].x, c.vertices[0].z, c.vertices[0].x, c.vertices[0].z};
    for (size_t i = 1; i < c.vertices.size(); ++i) {
      const float x = c.vertices[i].x, z = c.vertices[i].z;
      if (x < b.x0) b.x0 = x;
      if (x > b.x1) b.x1 = x;
      if (z < b.z0) b.z0 = z;
      if (z > b.z1) b.z1 = z;
    }
  }
  rsBoxes_.back() = b;
  roadStreamLiftSpills(reinterpret_cast<const float*>(c.vertices.data()), 4, c.vertices.size(),
                       c.stripRun, b);
  ++rsPlanChunks_;
  rsPlanVerts_ += it.verts;
  const size_t run = c.stripRun > 0 ? (size_t)c.stripRun : (size_t)75;
  rsPlanPackages_ += (int)((c.vertices.size() + run - 1) / run);
  if (c.stripRun <= 0) {
    rsPlanTriangles_ += (int)(c.vertices.size() / 3);
  } else {
    for (size_t at = 0; at < c.vertices.size(); at += run) {
      const size_t left = c.vertices.size() - at;
      const size_t len = left < run ? left : run;
      for (size_t k = 0; k + 2 < len; ++k) {
        const Tyra::Vec4& a = c.vertices[at + k];
        const Tyra::Vec4& bb = c.vertices[at + k + 1];
        const Tyra::Vec4& d = c.vertices[at + k + 2];
        const bool degenerate = (a.x == bb.x && a.y == bb.y && a.z == bb.z) ||
                                (bb.x == d.x && bb.y == d.y && bb.z == d.z) ||
                                (a.x == d.x && a.y == d.y && a.z == d.z);
        if (!degenerate) ++rsPlanTriangles_;
      }
    }
  }
}

// SPILLS: buildRoads lifts each spill vertex onto roadSurfaceAt over the
// COMPLETE road set (every strip and junction row of the scene, no spill).
// A streamed scene never holds that set, so the lift happens once, here, as
// the plan pass walks every surface chunk - the same triangle test, the same
// maximum - and rsSpillY_ keeps the answers (4 bytes a spill vertex).
void TerrainGame::roadStreamLiftSpills(const float* v, int stride, size_t count, int stripRun,
                                       const RsBox& box) {
  if (rsSpillY_.empty() || rsSpillXZ_.empty() || count < 3) return;
  for (int si = 0; si < ROAD_SPILL_COUNT; ++si) {
    if (rsSpillAt_[(size_t)si] < 0) continue;
    const RoadSpillRt& sp = ROAD_SPILLS[si];
    float* ys = &rsSpillY_[(size_t)rsSpillAt_[(size_t)si]];
    for (int k = 0; k < sp.count; ++k) {
      const float* sv = &rsSpillXZ_[(size_t)(rsSpillAt_[(size_t)si] + k) * 2];
      if (sv[0] < box.x0 || sv[0] > box.x1 || sv[1] < box.z0 || sv[1] > box.z1) continue;
      const float y = RsTri::highest(v, stride, count, stripRun, sv[0], sv[1]);
      if (y > ys[k]) ys[k] = y;
    }
  }
}

void TerrainGame::roadStreamAddItem(int kind, int a, int b, int verts, const float* v,
                                    int stride, int zAt, int count) {
  RsItem it;
  it.kind = (unsigned char)kind;
  it.a = a;
  it.b = b;
  it.verts = verts;
  rsItems_.push_back(it);
  RsBox box = {v[0], v[zAt], v[0], v[zAt]};
  for (int i = 1; i < count; ++i) {
    const float x = v[(size_t)i * (size_t)stride], z = v[(size_t)i * (size_t)stride + (size_t)zAt];
    if (x < box.x0) box.x0 = x;
    if (x > box.x1) box.x1 = x;
    if (z < box.z0) box.z0 = z;
    if (z > box.z1) box.z1 = z;
  }
  rsBoxes_.push_back(box);
}

void TerrainGame::roadStreamSetup(int scene) {
  const unsigned int stripRun = 75u;
  // The physical-GS smear that originally parked this at 0 came from unbounded
  // road V coordinates, not from strip topology. Each chunk now rebases V by a
  // whole repeat before either emitter sees it; hardware A/B keeps lane marks
  // intact while the strip removes hundreds of packages from a district.
  // Keep 0 as the triangle-list control arm for future renderer work.
#ifndef TYRA_STRIP_ROADS
#define TYRA_STRIP_ROADS 1
#endif
  const bool useStrips = TYRA_STRIP_ROADS && minPackageSize() >= stripRun;
  const Tyra::Color grey(128.0F, 128.0F, 128.0F, 128.0F);
  bool any = false;
  (void)any;
  (void)grey;
  const u32 rsT0 = profTicks();
  // Whatever an earlier scene left (loadScene clears procChunks anyway).
  bool erased = false;
  for (size_t i = procChunks.size(); i > 0; --i)
    if (procChunks[i - 1].owner <= -3 && procChunks[i - 1].owner >= -8) {
      procChunks.erase(procChunks.begin() + (i - 1));
      erased = true;
    }
  for (size_t i = procColliders.size(); i > 0; --i)
    if ((procColliders[i - 1].owner == -5 || procColliders[i - 1].owner == -7) &&
        procColliders[i - 1].instance <= -2)
      procColliders.erase(procColliders.begin() + (i - 1));
  if (erased) roadStreamRebindAll();
  rsItems_.clear();
  rsBoxes_.clear();
  rsOn_.clear();
  rsIndex_.clear();
  rsResident_.clear();
  rsFree_.clear();
  rsSpillY_.clear();
  rsSpillAt_.assign(ROAD_SPILL_COUNT > 0 ? (size_t)ROAD_SPILL_COUNT : (size_t)1, -1);
  rsPlanVerts_ = rsPlanChunks_ = rsPlanPackages_ = rsPlanTriangles_ = 0;
  rsPending_ = true;
  rsLastFoci_ = 0;
  roadStreamIoIdle();  // the old scene's reads and read-ahead go
  rsChunkCount_ = procChunks.size();
  for (int si = 0; si < ROAD_SPILL_COUNT; ++si) {
    const RoadSpillRt& sp = ROAD_SPILLS[si];
    if (sp.scene != scene) continue;
    rsSpillAt_[(size_t)si] = (int)rsSpillY_.size();
    rsSpillY_.insert(rsSpillY_.end(), (size_t)sp.count, -1.0e30F);
  }
  // TABLES ON DISK: open bin/roadfile/roads.bin (a missing or stale file is reported
  // here, loudly, once), then read the scene's spill rows - the lift below
  // needs every spill vertex's x and z before the strips are walked. Spills
  // are small (one per crossing decal); only x and z are kept, for the plan.
  roadStreamOpenFile();
  rsSpillXZ_.assign(rsSpillY_.size() * 2, 0.0F);
  rsSpillBox_ = RsBox{1.0e30F, 1.0e30F, -1.0e30F, -1.0e30F};
  if (rsFileState_ != 1) rsSpillXZ_.clear();
  for (int fi = 0; fi < ROAD_FILE_ITEM_COUNT && !rsSpillXZ_.empty(); ++fi) {
    const RoadFileItem& d = ROAD_FILE_ITEMS[fi];
    if ((int)d.scene != scene || d.kind != RS_SPILL) continue;
    unsigned char* rows = roadStreamReadNow(fi);
    if (!rows) {
      rsSpillXZ_.clear();  // no lift: the spills are not built (reported)
      break;
    }
    const float* v = reinterpret_cast<const float*>(rows);
    float* xz = &rsSpillXZ_[(size_t)rsSpillAt_[(size_t)d.row] * 2];
    for (int k = 0; k < d.count; ++k) {
      xz[k * 2] = v[k * 5];
      xz[k * 2 + 1] = v[k * 5 + 1];
    }
    free(rows);
    if (d.x0 < rsSpillBox_.x0) rsSpillBox_.x0 = d.x0;
    if (d.z0 < rsSpillBox_.z0) rsSpillBox_.z0 = d.z0;
    if (d.x1 > rsSpillBox_.x1) rsSpillBox_.x1 = d.x1;
    if (d.z1 > rsSpillBox_.z1) rsSpillBox_.z1 = d.z1;
  }
  // 1. Strip chunks: every road walked once, chunk by chunk, exactly as
  //    buildRoads cuts it - nothing kept but each chunk's resume state and box.
  for (int ri = 0; ri < ROAD_COUNT; ++ri) {
    const RoadDefRt& rd = ROAD_DEFS[ri];
    if (rd.scene != scene || rd.pointCount < 2) continue;
    roadStreamTessellate(ri, -1);
  }
  rsScratch_ = ProcChunk();  // the plan's buffers go back to the heap
  // 2-8. TABLES ON DISK: every baked row is an item of the directory the
  //    codegen wrote (ROAD_FILE_ITEMS), its box with it, so the plan reads
  //    no row. The junction rows that overlap a spill are read here once,
  //    for the spill lift - the only use of their vertices before a build.
  for (int fi = 0; fi < ROAD_FILE_ITEM_COUNT; ++fi) {
    const RoadFileItem& d = ROAD_FILE_ITEMS[fi];
    if ((int)d.scene != scene || d.kind != RS_JUNCTION) continue;
    roadStreamAddFileItem(fi, d.count);
    if (!rsSpillXZ_.empty() && d.x0 <= rsSpillBox_.x1 && d.x1 >= rsSpillBox_.x0 &&
        d.z0 <= rsSpillBox_.z1 && d.z1 >= rsSpillBox_.z0) {
      unsigned char* rows = roadStreamReadNow(fi);
      if (rows) {
        roadStreamLiftSpills(reinterpret_cast<const float*>(rows), 5, (size_t)d.count, 0,
                             rsBoxes_.back());
        free(rows);
      }
    }
    ++rsPlanChunks_;
    rsPlanVerts_ += d.count;
    rsPlanPackages_ += (d.count + 74) / 75;
    rsPlanTriangles_ += d.count / 3;
  }
  // 3. Spills: every surface under them has now been seen.
  for (int si = 0; si < ROAD_SPILL_COUNT; ++si) {
    const RoadSpillRt& sp = ROAD_SPILLS[si];
    if (sp.scene != scene || sp.count < 1 || rsSpillXZ_.empty()) continue;
    float* ys = &rsSpillY_[(size_t)rsSpillAt_[(size_t)si]];
    for (int k = 0; k < sp.count; ++k) {
      const float* sv = &rsSpillXZ_[(size_t)(rsSpillAt_[(size_t)si] + k) * 2];
      float y = ys[k];
      if (y < -1.0e29F) y = terrainHeightAt(sv[0], sv[1]) + 0.12F;
      ys[k] = y + 0.02F + sp.lift;
    }
  }
  std::vector<float>().swap(rsSpillXZ_);
  // 4-8. Spills, soft edges, kerbs and rails, bridge structure, details and
  //    furniture: one item per directory row.
  for (int fi = 0; fi < ROAD_FILE_ITEM_COUNT; ++fi) {
    const RoadFileItem& d = ROAD_FILE_ITEMS[fi];
    if ((int)d.scene != scene || d.kind == RS_JUNCTION) continue;
    roadStreamAddFileItem(fi, d.kind == RS_KERB && !useStrips ? d.count * 3 : d.count);
    if (d.kind == RS_SPILL || d.kind == RS_EDGE) {
      ++rsPlanChunks_;
      rsPlanVerts_ += d.count;
      rsPlanPackages_ += (d.count + 74) / 75;
      rsPlanTriangles_ += d.count / 3;
    }
  }
  // Bridge walls, one box at a time.
  for (int bi = 0; bi < ROAD_BRIDGE_BOX_COUNT; ++bi) {
    const float* b = &ROAD_BRIDGE_BOXES[(size_t)bi * 11];
    if ((int)b[0] != scene) continue;
    const float corners[6] = {b[1], b[2], b[3], b[4], b[5], b[6]};
    roadStreamAddItem(RS_BRIDGE_BOX, bi, 0, 0, corners, 3, 2, 2);
  }
  if (rsItems_.size() > 32000) {
    // The grid stores item ids in 16 bits and the collider tag in a short.
    TYRA_LOG("ROADSTREAM too many items (", (int)rsItems_.size(), "), the rest are dropped");
    rsItems_.resize(32000);
    rsBoxes_.resize(32000);
  }
  rsOn_.assign(rsItems_.size(), 0);
  rsIndex_.resize(rsItems_.size());
  rsBytes_.assign(rsItems_.size(), nullptr);
  rsQueued_.assign(rsItems_.size(), 0);
  rsBad_.assign(rsItems_.size(), 0);
  rsUseStamp_ = 0;
  rsGrid_.build(rsBoxes_.data(), (int)rsBoxes_.size(), ROAD_STREAM_CELL);
  TYRA_LOG("ROADS scene ", scene, " chunks ", rsPlanChunks_, " vertices ", rsPlanVerts_,
           " (streamed)");
  TYRA_LOG("ROADSTRIP scene ", scene, " strips ", useStrips ? 1 : 0, " packages ",
           rsPlanPackages_, " triangles ", rsPlanTriangles_);
  TYRA_LOG("ROADSTREAM plan scene ", scene, " items ", (int)rsItems_.size(), " cells ",
           rsGrid_.nx, "x", rsGrid_.nz, " radius ", (int)ROAD_STREAM_RADIUS, " keep ",
           (int)ROAD_STREAM_KEEP, " spill vertices ", (int)rsSpillY_.size(), " ms ",
           (int)((profTicks() - rsT0) / 294912U));
}

// Every bag's pointers into its chunk's arrays - after procChunks moved its
// elements (a reallocation, an erase), they point at the old addresses.
void TerrainGame::roadStreamRebindAll() {
  for (ProcChunk& c : procChunks) {
    if (!c.bag || !c.colorBag) continue;
    c.colors.bind(c.colorBag);
    c.vertices.bind(c.bag);
    if (c.bag->texture && c.texBag) c.sts.bind(c.texBag);
  }
}

// Which procChunks slot holds which item, read back from the chunks' tags -
// after anything else erased or inserted procChunks (a prefab despawn, a
// regenerated volume), the indices the items kept are stale.
void TerrainGame::roadStreamRemap() const {
  TerrainGame* self = const_cast<TerrainGame*>(this);
  for (RsItem& it : rsItems_)
    if (it.kind < RS_BRIDGE_BOX) it.chunk = -1;
  rsFree_.clear();
  for (size_t ci = 0; ci < procChunks.size(); ++ci) {
    const ProcChunk& c = procChunks[ci];
    if (c.owner == -8) {
      rsFree_.push_back((int)ci);
      continue;
    }
    if (c.owner > -3 || c.owner < -7 || c.instance > -2) continue;
    const int item = -2 - c.instance;
    if (item < (int)rsItems_.size()) rsItems_[(size_t)item].chunk = (int)ci;
  }
  self->roadStreamRebindAll();
  rsChunkCount_ = procChunks.size();
}

int TerrainGame::roadStreamSlot() {
  if (rsChunkCount_ != procChunks.size()) roadStreamRemap();
  while (!rsFree_.empty()) {
    const int slot = rsFree_.back();
    rsFree_.pop_back();
    if (slot >= 0 && slot < (int)procChunks.size() && procChunks[(size_t)slot].owner == -8)
      return slot;
  }
  const bool grows = procChunks.size() == procChunks.capacity();
  procChunks.emplace_back();
  procChunks.back().owner = -8;
  if (grows) roadStreamRebindAll();  // every chunk just moved
  rsChunkCount_ = procChunks.size();
  return (int)procChunks.size() - 1;
}

// procFinishChunks for ONE chunk - its loop body, cut from the template, so
// a streamed chunk gets exactly the bags, the box and the info bag the full
// pass would give it, without the full pass's walk over every chunk.
void TerrainGame::roadStreamFinish(ProcChunk& c) {
  if (!batchInfoBag) {
    batchInfoBag = std::make_unique<StaPipInfoBag>();
    batchInfoBag->model = &model;
    batchInfoBag->shadingType = TyraShadingGouraud;
    batchInfoBag->frustumCulling = PipelineInfoBagFrustumCulling_Precise;
    batchInfoBag->fullClipChecks = true;
  }
  do {
    if (c.vertices.empty()) {
      c.bag.reset();
      continue;
    }
    if (!c.bag) {
      c.colorBag = std::make_unique<StaPipColorBag>();
      c.bag = std::make_unique<StaPipBag>();
      c.bag->color = c.colorBag.get();
      c.bag->lighting = nullptr;
    }
    // Re-stated every pass, not only on creation: a regeneration reuses the
    // chunk, and a world whose blocks moved may have gained or lost the AO.
    c.bag->info = c.smooth ? procSmoothInfoBag.get() : batchInfoBag.get();
    if (c.roadBlend || c.roadEdge) {
      // A spill is alpha-over by its vertex alpha (the fade) on the road
      // under it, a soft edge on the terrain: the painted terrain layer's
      // arrangement.
      if (!roadBlendInfoBag) {
        roadBlendInfoBag = std::make_unique<StaPipInfoBag>();
        roadBlendInfoBag->model = &model;
        roadBlendInfoBag->shadingType = TyraShadingGouraud;
        roadBlendInfoBag->frustumCulling = PipelineInfoBagFrustumCulling_Precise;
        roadBlendInfoBag->fullClipChecks = true;
        roadBlendInfoBag->blendingEnabled = true;
      }
      c.bag->info = roadBlendInfoBag.get();
    }
    c.colors.bind(c.colorBag);
    c.vertices.bind(c.bag);
    c.bag->count = static_cast<u32>(c.vertices.size());
    // Triangle strips (docs/model-pipeline.md). A stripped chunk's array is
    // already chopped into self-contained runs, so the package size is PINNED
    // to the run rather than derived: StaPipCore slices a bag at multiples of
    // it, and a boundary anywhere else would fuse two strips. Nothing else is
    // derived either - the run is by construction no larger than any static
    // class's own capacity, which is what buildRoads checks before baking it.
    // Re-stated every pass, like the info bag above: a regeneration may have
    // turned a chunk from one representation into the other.
    c.bag->stripped = c.stripRun > 0;
    c.bag->packageSize = c.stripRun > 0 ? static_cast<u32>(c.stripRun) : 0U;
    c.bag->bboxVersion = ++g_bboxStamp;
    const Tyra::Texture* tex = c.roadTex;
    if (tex) {
    } else if (c.model >= 0 && c.model < (int)gameModels.size() &&
        c.part < (int)gameModels[c.model].parts.size())
      tex = gameModels[c.model].parts[c.part].texture;
    else if (c.material >= 0 && c.material < (int)gameMaterials.size())
      tex = gameMaterials[c.material].texture;
    if (tex) {
      if (!c.texBag) c.texBag = std::make_unique<StaPipTextureBag>();
      c.texBag->texture = const_cast<Tyra::Texture*>(tex);
      c.sts.bind(c.texBag);
      c.bag->texture = c.texBag.get();
    } else {
      c.bag->texture = nullptr;
    }
    c.aabbMin[0] = c.aabbMax[0] = c.vertices[0].x;
    c.aabbMin[1] = c.aabbMax[1] = c.vertices[0].y;
    c.aabbMin[2] = c.aabbMax[2] = c.vertices[0].z;
    for (const Vec4& v : c.vertices) {
      if (v.x < c.aabbMin[0]) c.aabbMin[0] = v.x;
      if (v.x > c.aabbMax[0]) c.aabbMax[0] = v.x;
      if (v.y < c.aabbMin[1]) c.aabbMin[1] = v.y;
      if (v.y > c.aabbMax[1]) c.aabbMax[1] = v.y;
      if (v.z < c.aabbMin[2]) c.aabbMin[2] = v.z;
      if (v.z > c.aabbMax[2]) c.aabbMax[2] = v.z;
    }
    for (int a = 0; a < 3; ++a)
      c.centre[a] = 0.5F * (c.aabbMin[a] + c.aabbMax[a]);
  } while (false);
}

void TerrainGame::roadStreamBuild(int item) {
  if (item < 0 || item >= (int)rsItems_.size() || rsOn_[(size_t)item]) return;
  RsItem& it = rsItems_[(size_t)item];
  const short tag = (short)(-2 - item);
  const unsigned int stripRun = 75u;
  // The physical-GS smear that originally parked this at 0 came from unbounded
  // road V coordinates, not from strip topology. Each chunk now rebases V by a
  // whole repeat before either emitter sees it; hardware A/B keeps lane marks
  // intact while the strip removes hundreds of packages from a district.
  // Keep 0 as the triangle-list control arm for future renderer work.
#ifndef TYRA_STRIP_ROADS
#define TYRA_STRIP_ROADS 1
#endif
  const bool useStrips = TYRA_STRIP_ROADS && minPackageSize() >= stripRun;
  const Tyra::Color grey(128.0F, 128.0F, 128.0F, 128.0F);
  bool any = false;
  (void)any;
  (void)grey;
  (void)tag;
  // Tables on disk: a baked item's rows, read ahead by the reader.
  const unsigned char* bytes = it.file >= 0 ? rsBytes_[(size_t)item] : nullptr;
  if (it.file >= 0 && !bytes) return;  // not read yet: the ring asks again
  if (it.kind == RS_BRIDGE_BOX || it.kind == RS_FURN_BOX) {
    if (it.kind == RS_BRIDGE_BOX) {
      const float* b = &ROAD_BRIDGE_BOXES[(size_t)it.a * 11];
      StaticBox sb;
      for (int a = 0; a < 3; ++a) {
        sb.mn[a] = b[1 + a];
        sb.mx[a] = b[4 + a];
      }
      sb.lhx = b[7];
      sb.lhz = b[8];
      sb.yc = b[9];
      sb.ys = b[10];
      sb.owner = -5;
      sb.instance = -1;
      procColliders.push_back(sb);
      procColliders.back().instance = tag;
    }
    rsOn_[(size_t)item] = 1;
    rsResident_.push_back(item);
    return;
  }
  const int slot = roadStreamSlot();
  procChunks[(size_t)slot] = ProcChunk();
  ProcChunk& c = procChunks[(size_t)slot];
  c.instance = -2 - item;
  it.chunk = slot;
  if (it.verts > 0) {
    c.vertices.reserve((size_t)it.verts);
    c.colors.reserve((size_t)it.verts);
    if (it.kind != RS_KERB && it.kind != RS_BRIDGE && it.kind != RS_FURN)
      c.sts.reserve((size_t)it.verts);
  }
  switch (it.kind) {
    case RS_STRIP:
      rsTarget_ = slot;
      roadStreamTessellate(it.a, item);
      if ((int)c.vertices.size() != it.verts && ++rsMismatch_ <= 4)
        TYRA_LOG("ROADSTREAM replay mismatch item ", item, " road ", it.a, " planned ", it.verts,
                 " built ", (int)c.vertices.size());
      break;
    case RS_JUNCTION: {
      RoadJunctionRt j = ROAD_JUNCTIONS[it.a];
      Tyra::Texture* tex = roadStreamTexture(j.tex);
      const int first = it.b;
      // Tables on disk: the bytes are this piece; the cut below reads
      // ROAD_JUNCTION_VERTS[(j.first + first + k) * 5], so j.first = -first.
      j.first = -first;
      const float* ROAD_JUNCTION_VERTS = reinterpret_cast<const float*>(bytes);
      c.owner = -3;
      c.roadTex = tex;
      c.roadGrip = j.grip;
      c.stripRun = 0;
      // A painted row (node markings, 1.171.0) carries its own colour; a
      // patch takes the road grey its texture modulates. Paint WITH a texture
      // (the worn road-paint) is alpha-blended by that texture's alpha onto
      // the asphalt, its colour halved (128 = 1 when it modulates a texel).
      const bool paintTex = j.rgb != 0 && tex != nullptr;
      const float pk = paintTex ? 0.5F : 1.0F;
      const Tyra::Color paint((float)((j.rgb >> 16) & 255) * pk,
                              (float)((j.rgb >> 8) & 255) * pk,
                              (float)(j.rgb & 255) * pk, 128.0F);
      const Tyra::Color& shade = j.rgb != 0 ? paint : grey;
      if (paintTex) {
        c.roadBlend = true;
        c.roadGripBase = j.grip;  // no grip of its own: the road's, unblended
      }
      const int count = std::min(1800, j.count - first);
      for (int k = 0; k < count; ++k) {
        const float* v = &ROAD_JUNCTION_VERTS[(size_t)(j.first + first + k) * 5];
        c.vertices.push_back(Tyra::Vec4(v[0], v[1], v[2], 1.0F));
        c.sts.push_back(Tyra::Vec4(v[3], v[4], 1.0F, 0.0F));
        c.colors.push_back(shade);
      }
      break;
    }
    case RS_SPILL: {
      RoadSpillRt sp = ROAD_SPILLS[it.a];
      sp.first = 0;  // tables on disk: the bytes are this row
      const float* ROAD_SPILL_VERTS = reinterpret_cast<const float*>(bytes);
      const RoadDefRt& rd = ROAD_DEFS[sp.road];
      roadStreamTexture(rd.tex);
      const float* spillY = &rsSpillY_[(size_t)rsSpillAt_[(size_t)it.a]];
      size_t yi = 0;
      c.owner = -3;
      c.roadTex = (rd.tex >= 0 && rd.tex < ROAD_TEXTURE_COUNT)
                      ? roadTextures_[rd.tex]
                      : nullptr;
      c.roadGrip = sp.grip;
      c.roadGripBase = sp.baseGrip;
      c.roadBlend = true;
      c.stripRun = 0;
      // Integer V rebase, the road chunks' rule (the physical PS2's ST path).
      float vBase = 1.0e30F;
      for (int k = 0; k < sp.count; ++k)
        vBase = fminf(vBase, ROAD_SPILL_VERTS[(size_t)(sp.first + k) * 5 + 3]);
      vBase = floorf(vBase);
      for (int k = 0; k < sp.count; ++k) {
        const float* sv = &ROAD_SPILL_VERTS[(size_t)(sp.first + k) * 5];
        c.vertices.push_back(Tyra::Vec4(sv[0], spillY[yi++], sv[1], 1.0F));
        c.sts.push_back(Tyra::Vec4(sv[2], sv[3] - vBase, 1.0F, 0.0F));
        c.colors.push_back(Tyra::Color(128.0F, 128.0F, 128.0F, sv[4] * 128.0F));
      }
      break;
    }
    case RS_EDGE: {
      RoadSpillRt ed = ROAD_EDGES[it.a];
      const RoadDefRt& rd = ROAD_DEFS[ed.road];
      Tyra::Texture* tex = roadStreamTexture(rd.tex);
      const int at = it.b;
      ed.first = -at;  // tables on disk: the bytes are this piece
      const float* ROAD_EDGE_VERTS = reinterpret_cast<const float*>(bytes);
      const int n = ed.count - at < 1800 ? ed.count - at : 1800;
      c.owner = -3;
      c.roadTex = tex;
      c.roadGrip = rd.grip;
      c.roadEdge = true;
      c.stripRun = 0;
      float vBase = 1.0e30F;
      for (int k = 0; k < n; ++k)
        vBase = fminf(vBase, ROAD_EDGE_VERTS[(size_t)(ed.first + at + k) * 5 + 3]);
      vBase = floorf(vBase);
      for (int k = 0; k < n; ++k) {
        const float* ev = &ROAD_EDGE_VERTS[(size_t)(ed.first + at + k) * 5];
        c.vertices.push_back(Tyra::Vec4(
            ev[0], terrainHeightAt(ev[0], ev[1]) + 0.12F + rd.lift, ev[1], 1.0F));
        c.sts.push_back(Tyra::Vec4(ev[2], ev[3] - vBase, 1.0F, 0.0F));
        c.colors.push_back(Tyra::Color(128.0F, 128.0F, 128.0F, ev[4] * 128.0F));
      }
      break;
    }
    case RS_KERB: {
      RoadKerbRt kr = ROAD_KERBS[it.a];
      kr.first = 0;  // tables on disk: the bytes are this row
      const float* ROAD_KERB_VERTS = reinterpret_cast<const float*>(bytes);
      int kerbTriangles = 0;
    auto same = [](const float* a, const float* b) {
      return a[0] == b[0] && a[1] == b[1] && a[2] == b[2];
    };
      c.owner = -4;
      c.drawDist = ROAD_KERB_DRAW_DISTANCE;
      c.stripRun = useStrips ? (int)stripRun : 0;
      auto put = [&](const float* v) {
        c.vertices.push_back(Tyra::Vec4(v[0], v[1], v[2], 1.0F));
        if (v[3] >= 1.5F) {
          // Rails (docs/roads.md "Rails and tram tracks"): a shade of 2+
          // names a ROAD_KERB_PALETTE colour (roadrail::shadeRgb's rule).
          int k = (int)v[3] - 2;
          if (k < 0) k = 0;
          if (k > 3) k = 3;
          const float* pc = ROAD_KERB_PALETTE[k];
          c.colors.push_back(
              Tyra::Color(pc[0] * 128.0F, pc[1] * 128.0F, pc[2] * 128.0F, 128.0F));
          return;
        }
        const float g = v[3] * 128.0F;  // light concrete, a hair warm
        c.colors.push_back(Tyra::Color(g, g * 0.98F, g * 0.94F, 128.0F));
      };
      const float* base = &ROAD_KERB_VERTS[(size_t)kr.first * 4];
      for (int at = 0; at < kr.count; at += 75) {
        const int len = kr.count - at < 75 ? kr.count - at : 75;
        for (int k = 0; k + 2 < len; ++k) {
          const float* a = base + (size_t)(at + k) * 4;
          if (same(a, a + 4) || same(a + 4, a + 8) || same(a, a + 8)) continue;
          ++kerbTriangles;
          // The list control arm (TYRA_STRIP_ROADS 0): the same triangles.
          if (!useStrips) { put(a); put(a + 4); put(a + 8); }
        }
      }
      if (useStrips)
        for (int k = 0; k < kr.count; ++k) put(base + (size_t)k * 4);
      (void)kerbTriangles;
      break;
    }
    case RS_BRIDGE: {
      RoadBridgeRt br = ROAD_BRIDGES[it.a];
      br.first = 0;  // tables on disk: the bytes are this row
      const float* ROAD_BRIDGE_VERTS = reinterpret_cast<const float*>(bytes);
      c.owner = -5;
      c.stripRun = 0;
      const float* base = &ROAD_BRIDGE_VERTS[(size_t)br.first * 4];
      for (int k = 0; k < br.count; ++k) {
        const float* v = base + (size_t)k * 4;
        c.vertices.push_back(Tyra::Vec4(v[0], v[1], v[2], 1.0F));
        const float g = v[3] * 128.0F;  // concrete, a hair warm
        c.colors.push_back(Tyra::Color(g, g * 0.99F, g * 0.96F, 128.0F));
      }
      break;
    }
    case RS_DETAIL: {
      RoadDetailRt dr = ROAD_DETAILS[it.a];
      dr.first = 0;  // tables on disk: the bytes are this row
      const float* ROAD_DETAIL_VERTS = reinterpret_cast<const float*>(bytes);
    Tyra::Texture* detailTex = nullptr;
    if (ROAD_DETAIL_TEX >= 0 && ROAD_DETAIL_TEX < ROAD_TEXTURE_COUNT) {
      if (!roadTextures_[ROAD_DETAIL_TEX])
        roadTextures_[ROAD_DETAIL_TEX] = acquireTexture(ROAD_TEXTURE_PATHS[ROAD_DETAIL_TEX]);
      detailTex = roadTextures_[ROAD_DETAIL_TEX];
    }
      if (!detailTex) break;
      c.owner = -6;
      c.roadTex = detailTex;
      c.roadBlend = true;
      c.drawDist = ROAD_DETAIL_DRAW_DISTANCE;
      c.stripRun = 0;
      const float* base = &ROAD_DETAIL_VERTS[(size_t)dr.first * 5];
      for (int k = 0; k < dr.count; ++k) {
        const float* v = base + (size_t)k * 5;
        c.vertices.push_back(Tyra::Vec4(v[0], v[1], v[2], 1.0F));
        c.sts.push_back(Tyra::Vec4(v[3], v[4], 1.0F, 0.0F));
        c.colors.push_back(grey);
      }
      break;
    }
    default:
      break;
  }
  roadStreamFinish(c);
  roadStreamFreeBytes(item);  // expanded: the rows go back to the heap
  if (it.kind <= RS_KERB &&
      !rsIndex_[(size_t)item].build(reinterpret_cast<const float*>(c.vertices.data()),
                                    c.vertices.size(), c.stripRun))
    TYRA_LOG("ROADSTREAM item ", item, " too large for its height index");
  rsOn_[(size_t)item] = 1;
  rsResident_.push_back(item);
}

// Frees one item's geometry (or its collision box). The caller takes it off
// rsResident_.
void TerrainGame::roadStreamDrop(int item) {
  RsItem& it = rsItems_[(size_t)item];
  if (!rsOn_[(size_t)item]) return;
  rsOn_[(size_t)item] = 0;
  if (it.kind == RS_BRIDGE_BOX || it.kind == RS_FURN_BOX) {
    const short tag = (short)(-2 - item);
    for (size_t i = procColliders.size(); i > 0; --i)
      if (procColliders[i - 1].instance == tag &&
          (procColliders[i - 1].owner == -5 || procColliders[i - 1].owner == -7)) {
        procColliders.erase(procColliders.begin() + (i - 1));
        break;
      }
    return;
  }
  if (rsChunkCount_ != procChunks.size() || it.chunk < 0 ||
      it.chunk >= (int)procChunks.size() ||
      procChunks[(size_t)it.chunk].instance != -2 - item)
    roadStreamRemap();
  if (it.chunk >= 0) {
    procChunks[(size_t)it.chunk] = ProcChunk();  // arrays and bags back to the heap
    procChunks[(size_t)it.chunk].owner = -8;
    rsFree_.push_back(it.chunk);
  }
  it.chunk = -1;
  rsIndex_[(size_t)item] = RsLocalIndex();
}

// One streaming step (tables on disk): finished reads join the cache; drop
// what is beyond the keep radius of every focus; then walk the items within
// radius + ROAD_STREAM_PREFETCH, nearest first - an item whose rows are not
// read yet is handed to the reader (and, inside the radius, waited for:
// the frame never blocks on it), an item inside the radius with its rows is
// built until the budget is spent (always at least one). budget < 0 =
// ROAD_STREAM_BUDGET; loadScene passes "all", and then the rows inside the
// radius are read right here, with the reader idle.
void TerrainGame::roadStreamUpdate(float fx, float fz, float f2x, float f2z, bool two,
                                   int budget) {
  if (rsItems_.empty()) return;
  if (budget < 0) budget = ROAD_STREAM_BUDGET;
  const bool drain = budget > 0x1000000;
  const float foci[4] = {fx, fz, f2x, f2z};
  const int nf = two ? 2 : 1;
  roadStreamIoCollect();
  // Nothing to do until a focus has moved a little or a build/read is pending.
  if (!rsPending_ && nf == rsLastFoci_) {
    bool moved = false;
    for (int f = 0; f < nf && !moved; ++f) {
      const float dx = foci[f * 2] - rsLastFocus_[f * 2];
      const float dz = foci[f * 2 + 1] - rsLastFocus_[f * 2 + 1];
      moved = dx * dx + dz * dz > 4.0F;
    }
    if (!moved) return;
  }
  for (int f = 0; f < 4; ++f) rsLastFocus_[f] = foci[f];
  rsLastFoci_ = nf;
  const u32 t0 = profTicks();
  ++rsUseStamp_;
  for (size_t r = 0; r < rsResident_.size();) {
    const int item = rsResident_[r];
    if (RsRing::keepItem(rsBoxes_[(size_t)item], foci, nf, ROAD_STREAM_KEEP)) {
      ++r;
      continue;
    }
    roadStreamDrop(item);
    rsResident_[r] = rsResident_.back();
    rsResident_.pop_back();
    ++rsStatDropped_;
  }
  // Rows read ahead for an item the ring has since left behind are not kept.
  for (size_t c = rsCache_.items.size(); c > 0; --c) {
    const int item = rsCache_.items[c - 1];
    if (!RsRing::keepItem(rsBoxes_[(size_t)item], foci, nf, ROAD_STREAM_KEEP))
      roadStreamFreeBytes(item);
  }
  rsRing_.wanted(rsGrid_, rsBoxes_.data(), rsOn_.data(), (int)rsItems_.size(), foci, nf,
                 ROAD_STREAM_RADIUS + ROAD_STREAM_PREFETCH, rsLoad_, rsKeys_);
  const float r2 = ROAD_STREAM_RADIUS * ROAD_STREAM_RADIUS;
  int spent = 0;
  bool waiting = false;
  for (size_t w = 0; w < rsLoad_.size(); ++w) {
    const int item = rsLoad_[w];
    const RsItem& it = rsItems_[(size_t)item];
    const bool inside = rsKeys_[w] <= r2;
    if (it.file >= 0) {
      if (rsFileState_ != 1 || rsBad_[(size_t)item] >= 3) continue;  // reported, never built
      if (rsBytes_[(size_t)item]) {
        rsCache_.touch(item, rsUseStamp_);
      } else if (drain && inside) {
        unsigned char* rows = roadStreamReadNow(it.file);
        if (!rows) {
          rsBad_[(size_t)item] = 3;
          continue;
        }
        rsBytes_[(size_t)item] = rows;
        rsCache_.add(item, ROAD_FILE_ITEMS[it.file].bytes, rsUseStamp_);
      } else {
        if (!drain && !rsQueued_[(size_t)item]) roadStreamIoRequest(item);
        if (inside) {
          waiting = true;  // its rows are on the way; the frame does not wait
          ++rsStatLate_;
        }
        continue;
      }
    }
    if (!inside) continue;
    if (spent >= budget) {
      waiting = true;
      continue;  // keep walking: the reads further out are still issued
    }
    spent += it.verts * (it.kind == RS_STRIP ? 4 : 1) + 32;
    roadStreamBuild(item);
    ++rsStatBuilt_;
  }
  // The cap: past it, the least recently wanted read-ahead goes.
  while (rsCache_.total > ROAD_STREAM_CACHE) {
    const int victim = rsCache_.oldest();
    if (victim < 0) break;
    roadStreamFreeBytes(victim);
  }
  bool busy = false;
  for (const RsIoSlot& s : rsIo_) busy = busy || s.state != 0;
  rsPending_ = waiting || busy;
  const u32 ticks = profTicks() - t0;
  int verts = 0;
  size_t indexBytes = 0;
  auto residentTotals = [&]() {
    verts = 0;
    indexBytes = 0;
    for (const int item : rsResident_) {
      verts += rsItems_[(size_t)item].verts;
      indexBytes += rsIndex_[(size_t)item].bytes();
    }
  };
  if (drain) {
    // loadScene's drain: one line, and it does not count as a frame. The
    // ROADFILE line is the synchronous read throughput (the plan's reads too).
    residentTotals();
    TYRA_LOG("ROADSTREAM load resident ", (int)rsResident_.size(), "/", (int)rsItems_.size(),
             " vertices ", verts, " index KB ", (int)(indexBytes / 1024), " ms ",
             (int)(ticks / 294912U));
    TYRA_LOG("ROADFILE load reads ", rsNowReads_, " KB ", (int)(rsNowBytes_ / 1024U), " read ms ",
             (int)(rsNowTicks_ / 294912U), " KB/s ",
             rsNowTicks_ > 0 ? (int)((double)rsNowBytes_ / 1024.0 /
                                     ((double)rsNowTicks_ / 294912000.0))
                             : 0,
             " errors ", rsReadErrors_);
    rsNowReads_ = 0;
    rsNowBytes_ = rsNowTicks_ = 0;
    rsStatBuilt_ = rsStatDropped_ = 0;
    rsStatLate_ = 0;
    return;
  }
  rsStatTicks_ += ticks;
  if (ticks > rsStatWorst_) rsStatWorst_ = ticks;
  // The streaming log: a line a few seconds apart while the ring is moving -
  // what is resident, what moved, and the worst frame's streaming cost; and
  // what the reader read, how long it took (its own wall time, off the
  // frame), how often an item inside the radius had to wait for its rows
  // (late, in item-frames) and what sits read ahead.
  if (++rsStatFrames_ >= 150 && (rsStatBuilt_ > 0 || rsStatDropped_ > 0)) {
    residentTotals();
    TYRA_LOG("ROADSTREAM resident ", (int)rsResident_.size(), "/", (int)rsItems_.size(),
             " vertices ", verts, " index KB ", (int)(indexBytes / 1024), " built ",
             rsStatBuilt_, " dropped ", rsStatDropped_, " busy frames ", rsStatFrames_,
             " total us ", (int)(rsStatTicks_ / 295U), " worst us ",
             (int)(rsStatWorst_ / 295U));
    TYRA_LOG("ROADFILE reads ", rsStatReads_, " KB ", (int)(rsStatReadBytes_ / 1024U),
             " reader ms ", (int)(rsStatReadTicks_ / 294912U), " worst us ",
             (int)(rsStatReadWorst_ / 295U), " late ", rsStatLate_, " cached KB ",
             (int)(rsCache_.total / 1024U), " errors ", rsReadErrors_);
    rsStatFrames_ = 0;
    rsStatBuilt_ = rsStatDropped_ = 0;
    rsStatTicks_ = rsStatWorst_ = 0;
    rsStatReads_ = rsStatLate_ = 0;
    rsStatReadBytes_ = rsStatReadTicks_ = rsStatReadWorst_ = 0;
  }
}

// Is every surface item touching (x, z)'s cell resident? A car that is not
// being driven only simulates where this holds (docs/roads.md "Road
// streaming": far cars freeze rather than drop through an unbuilt road).
bool TerrainGame::roadStreamReady(float x, float z) const {
  const int cell = rsGrid_.cellAt(x, z);
  if (cell < 0) return true;  // no road anywhere near: the terrain is the ground
  for (unsigned int e = rsGrid_.start[(size_t)cell]; e < rsGrid_.start[(size_t)cell + 1]; ++e) {
    const int item = rsGrid_.items[e];
    if (rsItems_[(size_t)item].kind <= RS_KERB && !rsOn_[(size_t)item]) return false;
  }
  return true;
}

// ---------------------------------------------------------------------------
// Tables on disk (docs/roads.md "Tables on disk"): bin/roadfile/roads.bin, its reader
// thread and the read-ahead cache.
// ---------------------------------------------------------------------------
void TerrainGame::roadStreamFileError(int state, const char* hud, const char* detail) {
  rsFileState_ = state;
  snprintf(rsFileMsg_, sizeof(rsFileMsg_), "%s", hud);
  TYRA_LOG("ROADFILE ERROR ", detail,
           " - the baked road rows (junctions, pavements, kerbs, rails, bridges, details,"
           " furniture) will NOT be built. Rebuild the project: bin/",
           ROAD_FILE_NAME, " must come from the same build as the ELF.");
}

// Opens bin/roadfile/roads.bin and checks its header against this ELF's directory,
// once per boot; starts the reader. A failure is final for the boot (and
// says so, in the log and on screen) - the strips still stream, the baked
// rows are never built. Never fatal.
bool TerrainGame::roadStreamOpenFile() {
  if (rsFileState_ == 1) return true;
  if (rsFileState_ < 0) return false;
  const std::string path = Tyra::FileUtils::fromCwd(ROAD_FILE_NAME);
  char detail[200];
  rsFd_ = open(path.c_str(), O_RDONLY);
  if (rsFd_ < 0) {
    snprintf(detail, sizeof(detail), "cannot open %s", path.c_str());
    roadStreamFileError(-1, "ROAD DATA MISSING - SEE LOG", detail);
    return false;
  }
  unsigned char h[RsFile::kHeader];
  unsigned int items = 0, payload = 0, hash = 0;
  if (!rsReadRange(rsFd_, 0, RsFile::kHeader, h)) {
    snprintf(detail, sizeof(detail), "cannot read the header of %s", path.c_str());
    roadStreamFileError(-3, "ROAD DATA UNREADABLE - SEE LOG", detail);
    close(rsFd_);
    rsFd_ = -1;
    return false;
  }
  if (!RsFile::header(h, &items, &payload, &hash) || items != (unsigned int)ROAD_FILE_ITEM_COUNT ||
      payload != ROAD_FILE_BYTES || hash != ROAD_FILE_HASH) {
    snprintf(detail, sizeof(detail),
             "%s is stale: items %u bytes %u hash %08X, this ELF wants items %d bytes %u"
             " hash %08X",
             path.c_str(), items, payload, hash, ROAD_FILE_ITEM_COUNT, ROAD_FILE_BYTES,
             ROAD_FILE_HASH);
    roadStreamFileError(-2, "ROAD DATA STALE - REBUILD - SEE LOG", detail);
    close(rsFd_);
    rsFd_ = -1;
    return false;
  }
  // The reader thread, above the game's priority (0x40) and below the audio
  // threads (0x5, 0x6): it spends its life blocked on the IOP, and wakes only
  // to hand a finished read over - so a read is never stuck behind a frame.
  ee_sema_t sema;
  sema.count = 0;
  sema.init_count = 0;
  sema.max_count = 0x10000;
  sema.attr = 0;
  sema.option = 0;
  sema.wait_threads = 0;
  rsIoSema_ = CreateSema(&sema);
  void* gp = nullptr;
  asm volatile("move %0, $gp" : "=r"(gp));
  ee_thread_t th;
  memset(&th, 0, sizeof(th));
  th.func = reinterpret_cast<void*>(&TerrainGame::roadStreamIoMain);
  th.stack = rsIoStack;
  th.stack_size = (int)sizeof(rsIoStack);
  th.gp_reg = gp;
  th.initial_priority = 0x30;
  rsIoThread_ = rsIoSema_ >= 0 ? CreateThread(&th) : -1;
  if (rsIoThread_ < 0 || StartThread(rsIoThread_, this) < 0) {
    snprintf(detail, sizeof(detail), "cannot start the road reader thread (sema %d thread %d)",
             rsIoSema_, rsIoThread_);
    roadStreamFileError(-3, "ROAD DATA UNREADABLE - SEE LOG", detail);
    return false;
  }
  rsFileState_ = 1;
  TYRA_LOG("ROADFILE open ", path.c_str(), " items ", (int)items, " KB ", (int)(payload / 1024U));
  return true;
}

// The reader thread: the oldest queued slot, one seek and its reads, the
// checksum, done. Everything else (which item, the cache, the build) is the
// frame's.
void TerrainGame::roadStreamIoMain(void* self) {
  TerrainGame* g = static_cast<TerrainGame*>(self);
  for (;;) {
    WaitSema(g->rsIoSema_);
    RsIoSlot* s = nullptr;
    for (int i = 0; i < ROAD_IO_SLOTS; ++i) {
      RsIoSlot& c = g->rsIo_[i];
      if (c.state == 1 && (!s || (int)(c.ticket - s->ticket) < 0)) s = &c;
    }
    if (!s) continue;
    s->state = 2;
    const u32 t0 = profTicks();
    const bool read = rsReadRange(g->rsFd_, s->at, s->bytes, s->buf);
    const bool good = read && RsFile::sum(s->buf, s->bytes, RsFile::kSeed) == s->sum;
    s->ticks = profTicks() - t0;
    s->state = !read ? 4 : (good ? 3 : 5);
  }
}

// A synchronous read on the frame's thread - the plan and loadScene's drain
// only, when the reader is idle (roadStreamIoIdle ran). Null on failure.
unsigned char* TerrainGame::roadStreamReadNow(int fi) {
  if (rsFileState_ != 1 || fi < 0 || fi >= ROAD_FILE_ITEM_COUNT) return nullptr;
  const RoadFileItem& d = ROAD_FILE_ITEMS[fi];
  unsigned char* buf = static_cast<unsigned char*>(memalign(64, d.bytes > 0 ? d.bytes : 64U));
  if (!buf) {
    TYRA_LOG("ROADFILE out of memory reading item ", fi, " (", (int)d.bytes, " bytes)");
    return nullptr;
  }
  const u32 t0 = profTicks();
  const bool read = rsReadRange(rsFd_, d.at, d.bytes, buf);
  const bool good = read && RsFile::sum(buf, d.bytes, RsFile::kSeed) == d.sum;
  rsNowTicks_ += profTicks() - t0;
  ++rsNowReads_;
  rsNowBytes_ += d.bytes;
  if (!good) {
    if (++rsReadErrors_ <= 8)
      TYRA_LOG("ROADFILE ERROR item ", fi, " kind ", (int)d.kind, " row ", d.row, " at ",
               (int)d.at, " bytes ", (int)d.bytes, read ? ": checksum mismatch" : ": read failed");
    snprintf(rsFileMsg_, sizeof(rsFileMsg_), "%s", "ROAD DATA READ ERROR - SEE LOG");
    free(buf);
    return nullptr;
  }
  return buf;
}

// Hands one item to the reader. False = every slot is busy (the ring asks
// again next frame) or no memory for its rows.
bool TerrainGame::roadStreamIoRequest(int item) {
  const RsItem& it = rsItems_[(size_t)item];
  if (it.file < 0 || rsFileState_ != 1) return false;
  RsIoSlot* s = nullptr;
  for (RsIoSlot& c : rsIo_)
    if (c.state == 0) {
      s = &c;
      break;
    }
  if (!s) return false;
  const RoadFileItem& d = ROAD_FILE_ITEMS[it.file];
  unsigned char* buf = static_cast<unsigned char*>(memalign(64, d.bytes > 0 ? d.bytes : 64U));
  if (!buf) return false;
  s->item = item;
  s->at = d.at;
  s->bytes = d.bytes;
  s->sum = d.sum;
  s->ticket = ++rsIoTicket_;
  s->buf = buf;
  s->state = 1;
  rsQueued_[(size_t)item] = 1;
  SignalSema(rsIoSema_);
  return true;
}

// Every finished slot: good rows join the cache (unless their item no longer
// wants them), a failure is counted, logged and shown, and retried at most
// twice (a ps2link hiccup) before the item is given up.
void TerrainGame::roadStreamIoCollect() {
  for (RsIoSlot& s : rsIo_) {
    const int state = s.state;
    if (state < 3) continue;
    const int item = s.item;
    const bool valid = item >= 0 && item < (int)rsItems_.size();
    bool kept = false;
    if (state == 3) {
      ++rsStatReads_;
      rsStatReadBytes_ += s.bytes;
      rsStatReadTicks_ += s.ticks;
      if (s.ticks > rsStatReadWorst_) rsStatReadWorst_ = s.ticks;
      if (valid && !rsOn_[(size_t)item] && !rsBytes_[(size_t)item]) {
        rsBytes_[(size_t)item] = s.buf;
        rsCache_.add(item, s.bytes, rsUseStamp_);
        kept = true;
      }
    } else {
      if (valid && rsBad_[(size_t)item] < 3) ++rsBad_[(size_t)item];
      if (++rsReadErrors_ <= 8)
        TYRA_LOG("ROADFILE ERROR item ", item, " at ", (int)s.at, " bytes ", (int)s.bytes,
                 state == 4 ? ": read failed" : ": checksum mismatch",
                 valid && rsBad_[(size_t)item] >= 3 ? " (given up)" : " (will retry)");
      snprintf(rsFileMsg_, sizeof(rsFileMsg_), "%s", "ROAD DATA READ ERROR - SEE LOG");
    }
    if (!kept) free(s.buf);
    if (valid) rsQueued_[(size_t)item] = 0;
    s.buf = nullptr;
    s.item = -1;
    s.state = 0;
  }
}

// Waits out the reader's current read and drops everything queued or read
// ahead: a new scene's items are numbered afresh.
void TerrainGame::roadStreamIoIdle() {
  for (RsIoSlot& s : rsIo_) {
    // Queued and not picked: the reader runs above this thread, so it is
    // never between "found it queued" and "marked it reading" while we look.
    if (s.state == 1) s.state = 0;
    while (s.state == 2) Tyra::Threading::sleep(1);
    if (s.buf) free(s.buf);
    s.buf = nullptr;
    s.item = -1;
    s.state = 0;
  }
  for (const int item : rsCache_.items)
    if (item >= 0 && item < (int)rsBytes_.size() && rsBytes_[(size_t)item]) {
      free(rsBytes_[(size_t)item]);
      rsBytes_[(size_t)item] = nullptr;
    }
  rsCache_.clear();
}

void TerrainGame::roadStreamFreeBytes(int item) {
  if (item < 0 || item >= (int)rsBytes_.size() || !rsBytes_[(size_t)item]) return;
  free(rsBytes_[(size_t)item]);
  rsBytes_[(size_t)item] = nullptr;
  rsCache_.remove(item);
}

void TerrainGame::roadStreamAddFileItem(int fi, int verts) {
  const RoadFileItem& d = ROAD_FILE_ITEMS[fi];
  RsItem it;
  it.kind = (unsigned char)d.kind;
  it.a = d.row;
  it.b = d.first;
  it.verts = verts;
  it.file = fi;
  rsItems_.push_back(it);
  rsBoxes_.push_back(RsBox{d.x0, d.z0, d.x1, d.z1});
}

// The loud half of a bad road file: an out-of-memory load is a black screen,
// this must not be one. Drawn every frame over the scene, in the debug font
// every build ships.
void TerrainGame::roadStreamDrawError() {
  if (rsFileState_ >= 0 && rsReadErrors_ == 0) return;
  const float h = (float)engine->renderer.core.getSettings().getHeight();
  drawHudText(engine, rsFileMsg_, 16.0F, h * 0.5F);
}

// --- road traffic (docs/traffic.md) -----------------------------------------

// Defined further down the vehicle runtime (the vehiclesim::bodyRotation twin).
static void vehBodyRotation(float pitch, float yaw, float roll, float out[3]);

// Where the roads are not built (road streaming), a car is never spawned.
bool TerrainGame::trafficGroundReady(float x, float z) const {
  return roadStreamReady(x, z);
}

// Night for the traffic's headlights: the scene's day/night cycle with the
// sun under 2 degrees, else the hour a non-running cycle is baked at
// (TRAFFIC_NIGHT, host-computed with the same rule).
int TerrainGame::trafficNight() const {
  if (!TRAFFIC_HEADLIGHTS) return 0;  // Preferences > Traffic > Headlights at night off
  const int sc = currentScene >= 0 && currentScene < SCENE_COUNT ? currentScene : 0;
  if (daynight::active(sc)) return daynight::g_sun[1] < 0.0349F ? 1 : 0;
  return TRAFFIC_NIGHT[sc];
}

void TerrainGame::trafficSetup(int scene) {
  tf_ = TfSim();
  tfVehicle_.clear();
  tfLamps_.clear();
  tfLines_.clear();
  tfCarOf_.assign(VEHICLE_COUNT > 0 ? VEHICLE_COUNT : 1, -1);
  tfScene_ = scene;
  tfLenT_ = tfLogT_ = tfLaneNear_ = 0.0F;
  tfSpawned_ = tfRecycled_ = 0;
  tfRunLine_ = -1;
  tfLights_ = -1;
  tfLampSig_ = 0U;
  tfLampCount_ = 0;
  tfLampVerts_.resize(kTfLampMax * 12);
  tfLampCols_.resize(kTfLampMax * 12);
  const int* sc = TRAFFIC_SCENES[scene];
  TfGraph& g = tf_.g;
  g.green = TRAFFIC_GREEN;
  g.amber = TRAFFIC_AMBER;
  g.allRed = TRAFFIC_ALL_RED;
  g.speed = TRAFFIC_SPEED;
  // The scene's points are one contiguous run of TRAFFIC_PTS: point at it.
  const int base = sc[1] > 0 ? TRAFFIC_SEGS[sc[0]].first : 0;
  g.pts = &TRAFFIC_PTS[(size_t)base * 3];
  g.pointCount = 0;
  for (int k = 0; k < sc[1]; ++k) {
    const TrafficSegData& d = TRAFFIC_SEGS[sc[0] + k];
    TfSeg s;
    s.first = d.first - base;
    s.count = d.count;
    g.pointCount = s.first + s.count > g.pointCount ? s.first + s.count : g.pointCount;
    s.kind = d.kind;
    s.node = d.node;
    s.group = d.group;
    s.rank = d.rank;
    s.turn = d.turn;
    s.nextFirst = (int)g.next.size();
    s.nextCount = d.nextCount;
    for (int i = 0; i < d.nextCount; ++i) g.next.push_back(TRAFFIC_NEXT[d.nextFirst + i]);
    s.confFirst = (int)g.conf.size();
    s.confCount = d.confCount;
    for (int i = 0; i < d.confCount; ++i) g.conf.push_back(TRAFFIC_CONF[d.confFirst + i]);
    s.inner = d.inner;
    s.outer = d.outer;
    g.segs.push_back(s);
  }
  // TRAFFIC_NODE_SIGNAL is each node's phase count (0 = no lights); each
  // node's cycle is one slot per phase (the host toSim's twin).
  for (int k = 0; k < sc[3]; ++k) {
    TfNode n;
    const int ph = TRAFFIC_NODE_SIGNAL[sc[2] + k];
    n.signal = ph > 0 ? 1 : 0;
    n.phases = ph > 1 ? ph : 2;
    const float cyc = (float)n.phases * (TRAFFIC_GREEN + TRAFFIC_AMBER + TRAFFIC_ALL_RED);
    n.offset = fmodf((float)k * 7.31F, cyc);
    g.nodes.push_back(n);
  }
  g.finish(3.0F);
  for (int k = 0; k < sc[5]; ++k) {
    const TrafficLampData& d = TRAFFIC_LAMPS[sc[4] + k];
    tfLamps_.push_back({d.node, d.group, d.x, d.y, d.z, d.fx, d.fz, d.scale});
  }
  for (int si = 0; si < (int)g.segs.size(); ++si) {
    const TfSeg& G = g.segs[(size_t)si];
    if (G.kind != 0 || G.nextCount <= 0) continue;
    const TfSeg& C = g.segs[(size_t)g.next[(size_t)G.nextFirst]];
    if (C.kind == 1 && C.group >= 0 && C.node >= 0 && g.nodes[(size_t)C.node].signal)
      tfLines_.push_back({si, C.node, C.group});
  }
  // The appended cars (VEHICLES rows with wpFirst -2): parked out of the
  // world until the ring places them.
  for (int vi = 0; vi < vehicleCount_; ++vi) {
    VehicleRt& v = vehicles_[vi];
    if (v.wpFirst != -2) continue;
    tfCarOf_[(size_t)vi] = (int)tfVehicle_.size();
    tfVehicle_.push_back(vi);
    v.active = 0;
    if (v.object >= 0 && v.object < (int)runtimeObjects.size())
      runtimeObjects[v.object].visible = false;
  }
  tf_.reset((int)tfVehicle_.size());
  tf_.changing = TRAFFIC_LANE_CHANGES;
  int conns = 0, sig = 0;
  for (const TfSeg& G : g.segs) conns += G.kind == 1;
  for (const TfNode& n : g.nodes) sig += n.signal;
  TYRA_LOG("TRAFFIC scene ", scene, " lanes ", (int)g.lanes.size(), " connections ", conns,
           " points ", g.pointCount, " signals ", sig, " lamps ",
           (int)tfLamps_.size(), " cars ", (int)tfVehicle_.size());
}

void TerrainGame::trafficPlace(int car, int seg, float s) {
  const int vi = tfVehicle_[(size_t)car];
  VehicleRt& v = vehicles_[vi];
  if (v.damage > 0.0F || v.dentCount > 0 || v.piecesGone != 0U) repairVehicle(vi);
  const int obj = v.object, def = v.def, drv = v.driveable;
  const float scale = v.scale;
  v = VehicleRt();
  v.object = obj;
  v.def = def;
  v.driveable = drv;
  v.scale = scale;
  v.wpFirst = -2;
  v.active = 1;
  v.lightsOn = tfLights_ > 0 ? 2 : 0;  // lamps without the pool (see trafficFrame)
  float p[5];
  tf_.g.at(seg, s, p);
  v.pos[0] = p[0];
  v.pos[1] = p[1] + VEHICLE_DEFS[def].rideHeight * scale;
  v.pos[2] = p[2];
  v.yaw = atan2f(p[3], p[4]) * 57.29578F;
  v.speed = TRAFFIC_SPEED * 0.6F;
  v.aiPrevX = p[0];
  v.aiPrevZ = p[2];
  tf_.place(car, seg, s);
  TfCar& c = tf_.cars[(size_t)car];
  c.x = p[0];
  c.z = p[2];
  c.yaw = v.yaw;
  c.speed = v.speed;
  c.passed = 0;
  if (obj >= 0 && obj < (int)runtimeObjects.size()) runtimeObjects[obj].visible = true;
  ++tfSpawned_;
}

void TerrainGame::trafficRemove(int car) {
  const int vi = tfVehicle_[(size_t)car];
  VehicleRt& v = vehicles_[vi];
  tf_.remove(car);
  v.active = 0;
  if (v.object >= 0 && v.object < (int)runtimeObjects.size())
    runtimeObjects[v.object].visible = false;
  ++tfRecycled_;
}

// Once a frame, before the vehicle sub-steps: the signal clock, who is in the
// way, recycling the cars that fell behind and placing new ones out of view.
void TerrainGame::trafficFrame(float dt) {
  if (tfScene_ < 0 || tf_.g.segs.empty() || tfVehicle_.empty()) return;
  const u32 tfT0 = profTicks();
  ++tfFrames_;
  tf_.clock += dt;
  float fx = cameraLookAt.x, fz = cameraLookAt.z;
  if (vehicleDriver_ >= 0 && vehicleDriver_ < vehicleCount_) {
    fx = vehicles_[vehicleDriver_].pos[0];
    fz = vehicles_[vehicleDriver_].pos[2];
  } else if (PLAYER_INDEX >= 0) {
    fx = players[0].x;
    fz = players[0].z;
  }
  float cfx = cameraLookAt.x - cameraPosition.x, cfz = cameraLookAt.z - cameraPosition.z;
  {
    const float l = sqrtf(cfx * cfx + cfz * cfz);
    if (l > 1e-3F) {
      cfx /= l;
      cfz /= l;
    } else {
      cfx = 0.0F;
      cfz = 1.0F;
    }
  }
  // Everything that is not traffic is in the way: other cars, and the player
  // on foot.
  tf_.obst.clear();
  for (int vi = 0; vi < vehicleCount_; ++vi) {
    const VehicleRt& v = vehicles_[vi];
    if (!v.active || v.def < 0 || tfCarOf_[(size_t)vi] >= 0) continue;
    const VehicleDefData& s = VEHICLE_DEFS[v.def];
    tf_.obst.push_back({v.pos[0], v.pos[2], v.yaw, (0.5F * s.wheelBase + s.bodyOverhang) * v.scale,
                        v.speed});
  }
  if (vehicleDriver_ < 0 && PLAYER_INDEX >= 0)
    tf_.obst.push_back({players[0].x, players[0].z, players[0].yaw * 57.29578F, 0.4F, 0.0F});
  // Headlights: every traffic car switches them with the night (a cheap
  // test once a frame, the cars rewritten only when it flips).
  {
    const int night = trafficNight();
    if (night != tfLights_) {
      tfLights_ = night;
      // 2 = lamps and coronas without the projected pool (the hook in
      // renderVehicleGlow): a pool per moving car is what lights cost.
      for (int ci = 0; ci < (int)tfVehicle_.size(); ++ci)
        vehicles_[tfVehicle_[(size_t)ci]].lightsOn = night ? 2 : 0;
    }
  }
  const float R = TRAFFIC_RADIUS;
  int on = 0, atLine = 0;
  for (int ci = 0; ci < (int)tf_.cars.size(); ++ci) {
    TfCar& c = tf_.cars[(size_t)ci];
    if (!c.on) continue;
    const VehicleRt& v = vehicles_[tfVehicle_[(size_t)ci]];
    c.x = v.pos[0];
    c.z = v.pos[2];
    c.yaw = v.yaw;
    c.speed = v.speed;
    c.stopT = (v.speed > 0.3F || v.speed < -0.3F) ? 0.0F : c.stopT + dt;
    atLine += c.atLine;
    const float dx = v.pos[0] - fx, dz = v.pos[2] - fz;
    const float d = sqrtf(dx * dx + dz * dz);
    const float vx = v.pos[0] - cameraPosition.x, vz = v.pos[2] - cameraPosition.z;
    const float vd = sqrtf(vx * vx + vz * vz);
    const bool seen = vd < 160.0F && (vd < 6.0F || (vx * cfx + vz * cfz) > 0.4F * vd);
    const bool wrecked = VEHICLE_DEFS[v.def].damageMechanical > 0.5F && v.damage >= 0.999F;
    if (d > R * 1.25F || (!seen && (c.stopT > 45.0F || wrecked))) {
      trafficRemove(ci);
      continue;
    }
    ++on;
  }
  tfLenT_ -= dt;
  if (tfLenT_ <= 0.0F) {
    tfLenT_ = 1.0F;
    tfLaneNear_ = tf_.laneLengthNear(fx, fz, R);
  }
  int target = (int)(TRAFFIC_DENSITY * tfLaneNear_ / 100.0F + 0.5F);
  if (target > (int)tf_.cars.size()) target = (int)tf_.cars.size();
  tfTarget_ = target;
  if (on < target) {
    float s = 0.0F;
    const int seg = tf_.spawnPick(tfRng_, fx, fz, cfx, cfz, 0.45F, R * 0.4F, R, 14.0F, &s);
    if (seg >= 0) {
      float p[5];
      tf_.g.at(seg, s, p);
      if (trafficGroundReady(p[0], p[2]))
        for (int ci = 0; ci < (int)tf_.cars.size(); ++ci)
          if (!tf_.cars[(size_t)ci].on) {
            trafficPlace(ci, seg, s);
            ++on;
            break;
          }
    }
  }
  trafficRedLight();
  tfCoreTicks_ += profTicks() - tfT0;
  tfLogT_ += dt;
  if (tfLogT_ >= 5.0F) {
    tfLogT_ = 0.0F;
    const int n = tfFrames_ > 0 ? tfFrames_ : 1;
    TYRA_LOG("TRAFFIC cars ", on, "/", target, " lane ", (int)tfLaneNear_, " spawned ", tfSpawned_,
             " recycled ", tfRecycled_, " at a line ", atLine, " red runs ", tfRedRuns_,
             " lane changes ", tf_.laneChanges, " overtakes ", tf_.overtakes,
             " lights ", tfLights_ > 0 ? 1 : 0,
             " clock ", (int)tf_.clock, " far ", tfKinematic_ / n,
             " core us/frame ", (int)(tfCoreTicks_ / 295U / (u32)n),
             " vehicles us/frame ", (int)(tfStepTicks_ / 295U / (u32)n));
    tfSpawned_ = tfRecycled_ = 0;
    tf_.laneChanges = tf_.overtakes = 0;
    tfCoreTicks_ = tfStepTicks_ = 0U;
    tfFrames_ = 0;
    tfKinematic_ = 0;
  }
}

// The player's car crossing a stop line on red: a log line, and the count,
// node and speed in ScriptContext that the On Red Light Run flow node fires
// on (a graph cannot call the game; it watches the count move).
void TerrainGame::trafficRedLight() {
  if (vehicleDriver_ < 0 || vehicleDriver_ >= vehicleCount_ || tfLines_.empty()) {
    tfRunLine_ = -1;
    return;
  }
  const VehicleRt& v = vehicles_[vehicleDriver_];
  const float hx = sinf(v.yaw * 0.017453293F), hz = cosf(v.yaw * 0.017453293F);
  // The nearest line across (a car straddling the centre line, or between two
  // lanes of its direction, still crosses the line of the lane nearest it).
  int best = -1;
  float bestAlong = 0.0F, bestLat = 1e9F;
  for (int k = 0; k < (int)tfLines_.size(); ++k) {
    const TfSeg& G = tf_.g.segs[(size_t)tfLines_[(size_t)k].lane];
    const float* e = &tf_.g.pts[(size_t)(G.first + G.count - 1) * 3];
    const float* q = &tf_.g.pts[(size_t)(G.first + G.count - 2) * 3];
    float tx = e[0] - q[0], tz = e[2] - q[2];
    const float tl = sqrtf(tx * tx + tz * tz);
    if (tl < 1e-4F) continue;
    tx /= tl;
    tz /= tl;
    const float rx = v.pos[0] - e[0], rz = v.pos[2] - e[2];
    const float along = rx * tx + rz * tz, lat = rx * tz - rz * tx;
    const float al = lat < 0.0F ? -lat : lat;
    if (along > -8.0F && along < 4.0F && al < 4.5F && al < bestLat && hx * tx + hz * tz > 0.6F) {
      best = k;
      bestAlong = along;
      bestLat = al;
    }
  }
  if (best >= 0 && best == tfRunLine_ && tfRunAlong_ < 0.0F && bestAlong >= 0.0F) {
    const TfLine& l = tfLines_[(size_t)best];
    const int lt = tf_.g.light(l.node, l.group, tf_.clock);
    TYRA_LOG("TRAFFIC player crossed the line at node ", l.node, " on ",
             lt == 0 ? "green" : (lt == 1 ? "amber" : "red"));
    if (lt == 2) {
      ++tfRedRuns_;
      ++scriptCtx.redLightRuns;
      scriptCtx.redLightNode = l.node;
      scriptCtx.redLightSpeed = v.speed > 0.0F ? v.speed : -v.speed;
      TYRA_LOG("TRAFFIC red light run ", tfRedRuns_, " at node ", l.node, " speed ",
               (int)(scriptCtx.redLightSpeed * 10.0F) / 10.0F);
    }
  }
  tfRunLine_ = best;
  tfRunAlong_ = bestAlong;
}

// A traffic car's pedals and wheel, from the core - in place of the pad's or
// the waypoint AI's, so the sim, the walls and the damage are untouched.
void TerrainGame::trafficDrive(int vi, float& throttle, float& brake, float& steer) {
  const int ci = tfCarOf_[(size_t)vi];
  TfCar& c = tf_.cars[(size_t)ci];
  const VehicleRt& v = vehicles_[vi];
  const VehicleDefData& s = VEHICLE_DEFS[v.def];
  c.x = v.pos[0];
  c.z = v.pos[2];
  c.yaw = v.yaw;
  c.speed = v.speed;
  c.half = (0.5F * s.wheelBase + s.bodyOverhang) * v.scale;
  c.halfW = (0.5F * s.track + 0.35F) * v.scale;
  c.brake = s.brakeDecel;
  if (s.damageMechanical > 0.5F && v.damage >= 0.999F) {
    throttle = 0.0F;
    brake = 1.0F;
    steer = 0.0F;
    return;
  }
  const u32 t0 = profTicks();
  tf_.drive(ci, &throttle, &brake, &steer);
  tfCoreTicks_ += profTicks() - t0;
}

// FAR CARS (docs/traffic.md "What it costs"): a traffic car this far from
// the camera is drawn by its far tier, a few pixels tall - so it skips the
// vehicle sim (tyres, suspension, walls) and slides along its lane at the
// speed the core's pedals ask for, glued to the lane's own height. The full
// sim takes over again as it comes near; the lane keeps the two consistent.
bool TerrainGame::trafficKinematic(int vi, float dt, float throttle, float brake) {
  VehicleRt& v = vehicles_[vi];
  const VehicleDefData& s = VEHICLE_DEFS[v.def];
  const float dx = v.pos[0] - cameraPosition.x, dz = v.pos[2] - cameraPosition.z;
  const float nearD = s.trafficDistance + 30.0F > 45.0F ? s.trafficDistance + 30.0F : 45.0F;
  if (dx * dx + dz * dz < nearD * nearD) return false;
  TfCar& c = tf_.cars[(size_t)tfCarOf_[(size_t)vi]];
  float spd = v.speed > 0.0F ? v.speed : 0.0F;
  if (brake > 0.01F) spd -= s.brakeDecel * 0.6F * brake * dt;
  else if (throttle > 0.01F) spd += s.accel * throttle * dt;
  if (spd < 0.0F) spd = 0.0F;
  float p[5];
  tf_.pose(c, spd * dt, p);  // across a lane change in flight, blended
  const float SC = v.scale;
  v.pos[0] = p[0];
  v.pos[1] = p[1] + s.rideHeight * SC;
  v.pos[2] = p[2];
  if (spd > 0.05F) v.yaw = atan2f(p[3], p[4]) * 57.29578F;
  v.speed = spd;
  v.lateral = 0.0F;
  v.velY = 0.0F;
  v.pitch = v.roll = v.leanPitch = v.leanRoll = 0.0F;
  v.pitchVel = v.rollVel = 0.0F;
  v.grounded = 1;
  for (int k = 0; k < 4; ++k) v.wheelY[k] = p[1];
  ++tfKinematic_;
  if (v.object >= 0 && v.object < (int)runtimeObjects.size()) {
    RuntimeObject& o = runtimeObjects[v.object];
    o.data.position[0] = v.pos[0];
    o.data.position[1] = v.pos[1];
    o.data.position[2] = v.pos[2];
    vehBodyRotation(0.0F, v.yaw, 0.0F, o.data.rotation);
    if (vehSubStepMore_) {
      v.objMatPending = true;
    } else if (o.onMatrixPath) {
      updateObjMat(v.object);
      v.objMatPending = false;
    } else {
      o.dirty = true;
      v.objMatPending = false;
    }
  }
  return true;
}

// The lit lens of every signal head in reach: one quad (both windings) per
// head over its baked, unlit lens. Rewritten only when a light changes or a
// head comes into reach - otherwise the bag replays its stream.
void TerrainGame::renderTrafficLamps() {
  if (tfLamps_.empty()) return;
  unsigned int sig = 2166136261U;
  int count = 0;
  int pick[kTfLampMax];
  int lens[kTfLampMax];
  for (int k = 0; k < (int)tfLamps_.size() && count < kTfLampMax; ++k) {
    const TfLamp& l = tfLamps_[(size_t)k];
    const float dx = l.x - cameraPosition.x, dz = l.z - cameraPosition.z;
    if (dx * dx + dz * dz > 95.0F * 95.0F) continue;
    const int st = tf_.g.light(l.node, l.group, tf_.clock);
    pick[count] = k;
    lens[count] = st == 2 ? 0 : (st == 1 ? 1 : 2);
    sig = (sig ^ (unsigned int)(k * 4 + lens[count])) * 16777619U;
    ++count;
  }
  if (count <= 0) return;
  if (sig != tfLampSig_ || count != tfLampCount_) {
    tfLampSig_ = sig;
    tfLampCount_ = count;
    for (int i = 0; i < count; ++i) {
      const TfLamp& l = tfLamps_[(size_t)pick[i]];
      const int k = lens[i];
      const float sc = l.scale;
      const float h = (TRAFFIC_LENS_HALF + 0.01F) * sc;
      const float cz = (TRAFFIC_LENS_Z + 0.012F) * sc;
      const float cx = l.x + l.fx * cz, cy = l.y + TRAFFIC_LENS_Y[k] * sc, czz = l.z + l.fz * cz;
      const float rx = l.fz * h, rz = -l.fx * h;
      auto g = tfLampVerts_.span((size_t)i * 12, 12);
      auto c = tfLampCols_.span((size_t)i * 12, 12);
      g[0].set(cx - rx, cy - h, czz - rz, 1.0F);
      g[1].set(cx + rx, cy - h, czz + rz, 1.0F);
      g[2].set(cx + rx, cy + h, czz + rz, 1.0F);
      g[3] = g[0];
      g[4] = g[2];
      g[5].set(cx - rx, cy + h, czz - rz, 1.0F);
      for (int j = 0; j < 6; ++j) g[6 + j] = g[5 - j];
      const Tyra::Color col = k == 0 ? Tyra::Color(255.0F, 40.0F, 28.0F, 128.0F)
                            : (k == 1 ? Tyra::Color(255.0F, 175.0F, 30.0F, 128.0F)
                                      : Tyra::Color(70.0F, 255.0F, 120.0F, 128.0F));
      for (int j = 0; j < 12; ++j) c[j] = col;
    }
    if (tfLampBag_) tfLampBag_->bboxVersion = ++g_bboxStamp;
  }
  if (!tfLampBag_) {
    tfLampInfo_ = std::make_unique<StaPipInfoBag>();
    tfLampInfo_->model = &model;
    tfLampInfo_->shadingType = TyraShadingGouraud;
    tfLampInfo_->fullClipChecks = true;
    tfLampInfo_->frustumCulling = PipelineInfoBagFrustumCulling_Precise;
    tfLampInfo_->zTestType = PipelineZTest_Standard;
    tfLampColorBag_ = std::make_unique<StaPipColorBag>();
    tfLampCols_.bind(tfLampColorBag_);
    tfLampBag_ = std::make_unique<StaPipBag>();
    tfLampBag_->info = tfLampInfo_.get();
    tfLampBag_->color = tfLampColorBag_.get();
    tfLampBag_->lighting = nullptr;
    tfLampBag_->texture = nullptr;
    tfLampVerts_.bind(tfLampBag_);
    tfLampBag_->bboxVersion = ++g_bboxStamp;
  }
  tfLampBag_->count = (u32)(tfLampCount_ * 12);
  stapip.core.render(tfLampBag_.get());
}
 */
void TerrainGame::renderProcChunks() {
#if TYRA_FRAME_PROFILE
  stapip.core.setTelemetryProducer(Tyra::StaPipProducerProcedural);
#endif
  if (procChunks.empty()) return;
  for (ProcChunk& c : procChunks) {
    // Roads have their own phase and profiler row. Keeping them here as well
    // used to make "Procedural" mean "mostly asphalt" and would double-draw
    // them now that the main view calls renderRoadChunks explicitly.
    if (c.owner == -3 || c.owner == -6) continue;  // -6 draws with the roads
    if (!c.bag || c.bag->count == 0) continue;
    // StaPip has its own precise clipper, but entering it for every generated
    // road/prefab chunk still pays the bag setup and classification cost. The
    // chunks already own world-space bounds, so reject wholly invisible ones
    // here and leave only intersecting chunks to the pipeline's safe clipper.
    const Tyra::Vec4 mn(c.aabbMin[0], c.aabbMin[1], c.aabbMin[2], 1.0F);
    const Tyra::Vec4 mx(c.aabbMax[0], c.aabbMax[1], c.aabbMax[2], 1.0F);
    if (Tyra::CoreBBox::frustumCheckAABB(
            engine->renderer.core.renderer3D.frustumPlanes.getAll(), mn, mx) ==
        Tyra::CoreBBoxFrustum::OUTSIDE_FRUSTUM)
      continue;
    // Per-chunk draw distance: the cheapest LOD there is, and the reason
    // chunk size is a real authoring decision rather than a detail.
    if (c.drawDist > 0.0F) {
      const float dx = c.centre[0] - cameraPosition.x;
      const float dy = c.centre[1] - cameraPosition.y;
      const float dz = c.centre[2] - cameraPosition.z;
      if (dx * dx + dy * dy + dz * dz > c.drawDist * c.drawDist) continue;
    }
    if (splitBandActive && outsideSplitBand(c.aabbMin, c.aabbMax)) continue;
    if (occlusionHiddenAabb(c.aabbMin, c.aabbMax)) continue;
    stapip.core.render(c.bag.get());
  }
}
